'use strict';
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// --- AppError base ---
const base = new AppError('something broke', 503, 'TEST', { a: 1 });
console.assert(base.statusCode  === 503,    'AppError statusCode');
console.assert(base.code        === 'TEST', 'AppError code');
console.assert(base.isOperational === true, 'AppError isOperational default');
console.assert(JSON.stringify(base.toJSON()).includes('TEST'), 'AppError toJSON code');
console.assert(JSON.stringify(base.toJSON()).includes('something broke'), 'AppError toJSON message');
console.assert(JSON.stringify(base.toJSON()).includes('details'), 'AppError toJSON details');
console.log('✓ AppError');

// --- NotFoundError ---
const nfe1 = new NotFoundError('User', '99');
console.assert(nfe1 instanceof AppError,   'NotFoundError extends AppError');
console.assert(nfe1.statusCode === 404,    'NotFoundError statusCode');
console.assert(nfe1.code === 'NOT_FOUND',  'NotFoundError code');
console.assert(nfe1.message.includes('99'), 'NotFoundError message includes id');
const nfe2 = new NotFoundError();
console.assert(nfe2.message === 'Resource was not found.', 'NotFoundError default message');
console.log('✓ NotFoundError');

// --- ValidationError ---
const ve1 = new ValidationError('Bad input', [{ field: 'email', message: 'invalid' }]);
console.assert(ve1 instanceof AppError,          'ValidationError extends AppError');
console.assert(ve1.statusCode === 422,           'ValidationError statusCode');
console.assert(ve1.code === 'VALIDATION_ERROR',  'ValidationError code');
const ve1Json = JSON.stringify(ve1.toJSON());
console.assert(ve1Json.includes('email'),        'ValidationError toJSON includes field');
const ve2 = ValidationError.fromFieldMap({ name: 'required', age: 'must be number' });
console.assert(ve2.details.fields.length === 2,  'fromFieldMap field count');
console.log('✓ ValidationError');

// --- DatabaseError ---
const cause = new Error('PG timeout');
const de = new DatabaseError('Write failed', cause, 'insert');
console.assert(de instanceof AppError,        'DatabaseError extends AppError');
console.assert(de.statusCode === 503,         'DatabaseError statusCode');
console.assert(de.code === 'DATABASE_ERROR',  'DatabaseError code');
console.assert(de.cause === cause,            'DatabaseError preserves cause');
const deJson = JSON.stringify(de.toJSON());
console.assert(!deJson.includes('PG timeout'), 'DatabaseError cause not in toJSON');
console.assert(deJson.includes('insert'),       'DatabaseError operation in details');
console.log('✓ DatabaseError');

// --- instanceof chain ---
console.assert(nfe1 instanceof NotFoundError,   'instanceof NotFoundError');
console.assert(nfe1 instanceof AppError,        'instanceof AppError');
console.assert(nfe1 instanceof Error,           'instanceof Error');
console.log('✓ instanceof chain');

console.log('All error class tests passed.');
