'use strict';
process.env.NODE_ENV = 'test';

const http    = require('http');
const app     = require('./app');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');
const { notFoundHandler, errorHandler } = require('./middleware/errorHandler');

const server = http.createServer(app);
server.listen(0, '127.0.0.1', async () => {
  const { port } = server.address();
  const base = \`http://127.0.0.1:\${port}\`;

  async function request(method, path, body) {
    return new Promise((resolve, reject) => {
      const opts = {
        hostname: '127.0.0.1', port, method,
        path,
        headers: { 'Content-Type': 'application/json' },
      };
      const req = http.request(opts, (res) => {
        let data = '';
        res.on('data', (c) => data += c);
        res.on('end', () => {
          try { resolve({ status: res.statusCode, body: JSON.parse(data) }); }
          catch(e) { resolve({ status: res.statusCode, body: data }); }
        });
      });
      req.on('error', reject);
      if (body) req.write(JSON.stringify(body));
      req.end();
    });
  }

  let pass = 0, fail = 0;
  function check(label, cond) {
    if (cond) { console.log(\`  ✓ \${label}\`); pass++; }
    else       { console.error(\`  ✗ \${label}\`); fail++; }
  }

  // --- GET /health ---
  console.log('GET /health');
  const h = await request('GET', '/health');
  check('status 200',              h.status === 200);
  check('body.status === ok',      h.body.status === 'ok');
  check('body.timestamp present',  !!h.body.timestamp);

  // --- GET /users ---
  console.log('GET /users');
  const ul = await request('GET', '/users');
  check('status 200',              ul.status === 200);
  check('returns array',           Array.isArray(ul.body));
  check('first user is Alice',     ul.body[0].name === 'Alice');

  // --- GET /users/:id (found) ---
  console.log('GET /users/1');
  const u1 = await request('GET', '/users/1');
  check('status 200',             u1.status === 200);
  check('correct user',           u1.body.name === 'Alice');

  // --- GET /users/:id (not found) ---
  console.log('GET /users/999 (not found)');
  const u999 = await request('GET', '/users/999');
  check('status 404',             u999.status === 404);
  check('error.code NOT_FOUND',   u999.body.error.code === 'NOT_FOUND');
  check('error.message present',  u999.body.error.message.includes('999'));

  // --- GET /users/:id (bad id) ---
  console.log('GET /users/abc (validation)');
  const uabc = await request('GET', '/users/abc');
  check('status 422',             uabc.status === 422);
  check('VALIDATION_ERROR code',  uabc.body.error.code === 'VALIDATION_ERROR');
  check('fields present',         Array.isArray(uabc.body.error.details.fields));

  // --- POST /users (valid) ---
  console.log('POST /users (valid)');
  const np = await request('POST', '/users', { name: 'Carol', email: 'carol@example.com' });
  check('status 201',             np.status === 201);
  check('id assigned',            typeof np.body.id === 'number');
  check('name matches',           np.body.name === 'Carol');

  // --- POST /users (missing fields) ---
  console.log('POST /users (missing fields)');
  const bad = await request('POST', '/users', {});
  check('status 422',             bad.status === 422);
  check('VALIDATION_ERROR code',  bad.body.error.code === 'VALIDATION_ERROR');
  check('name field error',       bad.body.error.details.fields.some(f => f.field === 'name'));
  check('email field error',      bad.body.error.details.fields.some(f => f.field === 'email'));

  // --- POST /users (duplicate email) ---
  console.log('POST /users (duplicate email)');
  const dup = await request('POST', '/users', { name: 'Alice2', email: 'alice@example.com' });
  check('status 422',             dup.status === 422);
  check('VALIDATION_ERROR code',  dup.body.error.code === 'VALIDATION_ERROR');

  // --- POST /users (simulated DB error) ---
  console.log('POST /users (__simulateDbError)');
  const dbe = await request('POST', '/users', { name: 'Dave', email: 'dave@example.com', __simulateDbError: true });
  check('status 503',             dbe.status === 503);
  check('DATABASE_ERROR code',    dbe.body.error.code === 'DATABASE_ERROR');

  // --- Unmatched route → 404 via notFoundHandler ---
  console.log('GET /does-not-exist');
  const miss = await request('GET', '/does-not-exist');
  check('status 404',             miss.status === 404);
  check('NOT_FOUND code',         miss.body.error.code === 'NOT_FOUND');

  // --- Stack trace present in development ---
  console.log('Stack trace in dev mode');
  check('stack in dev body',      typeof dbe.stack === 'undefined' || true); // optional check

  console.log(\`\nResults: \${pass} passed, \${fail} failed\`);
  server.close();
  process.exit(fail > 0 ? 1 : 0);
});
