/**
 * errors.js
 *
 * Centralised error class hierarchy for the Express application.
 *
 * All custom errors extend AppError, which itself extends the native Error
 * class.  Every AppError carries:
 *   - statusCode  – the HTTP status code that should be sent to the client
 *   - code        – a stable machine-readable string (useful for clients and
 *                   logging pipelines)
 *   - isOperational – true for anticipated, "safe-to-surface" errors
 *                     (validation failures, missing resources, …) vs.
 *                     programmer mistakes / unexpected failures where
 *                     isOperational is false.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description.
   * @param {number}  statusCode    - HTTP status code.
   * @param {string}  code          - Machine-readable error code.
   * @param {boolean} isOperational - Whether the error is expected /
   *                                  safe to expose to callers.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work even
    // after TypeScript / Babel compilation (not needed here, but good habit).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.code       = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts from the call-site, not from
    // inside this constructor.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – resource not found
// ---------------------------------------------------------------------------

/**
 * Throw when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Product ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {string} [code='NOT_FOUND']
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

// ---------------------------------------------------------------------------
// 422 – validation / business-rule failure
// ---------------------------------------------------------------------------

/**
 * Throw when incoming data fails validation or violates a business rule.
 * An optional `details` array can carry per-field error objects for richer
 * client feedback (e.g. from a Joi / Zod result).
 *
 * @example
 *   throw new ValidationError('Email is required');
 *   throw new ValidationError('Invalid payload', 'INVALID_PAYLOAD', [
 *     { field: 'email', message: 'must be a valid email address' },
 *   ]);
 */
class ValidationError extends AppError {
  /**
   * @param {string}   [message='Validation failed']
   * @param {string}   [code='VALIDATION_ERROR']
   * @param {Array<{field: string, message: string}>} [details=[]]
   */
  constructor(
    message = 'Validation failed',
    code    = 'VALIDATION_ERROR',
    details = [],
  ) {
    super(message, 422, code);
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// 503 – database / downstream service failure
// ---------------------------------------------------------------------------

/**
 * Throw (or wrap a caught error with) when a database query or connection
 * fails.  Marked as non-operational by default because the application
 * cannot continue serving requests normally; the error handler will return
 * a generic 503 and avoid leaking internal details.
 *
 * @example
 *   try {
 *     await db.query(sql);
 *   } catch (cause) {
 *     throw new DatabaseError('Failed to fetch users', 'DB_QUERY_FAILED', cause);
 *   }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {string} [code='DATABASE_ERROR']
   * @param {Error|null} [cause=null] - The original low-level error.
   */
  constructor(
    message = 'A database error occurred',
    code    = 'DATABASE_ERROR',
    cause   = null,
  ) {
    // DatabaseError is not operational: it signals an infrastructure problem
    // rather than a recoverable client mistake.
    super(message, 503, code, /* isOperational */ false);

    if (cause) {
      // Preserve the root cause for logging without exposing it to clients.
      this.cause = cause;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 *
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 *  1. Route / middleware throws (or calls next(err) with) any Error.
 *  2. The 404 catch-all converts unmatched routes into NotFoundErrors.
 *  3. errorHandler() is the single place that translates errors into HTTP
 *     responses, so individual routes stay free of res.status().json() error
 *     boilerplate.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Liveness probe – always returns 200 while the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns a static list of users.
 * Demonstrates: no errors expected on the happy path; DatabaseError thrown
 * when the (simulated) data layer fails.
 */
app.get('/users', (req, res) => {
  // In a real application this would be an async function with `await db.find(…)`.
  // The try/catch below shows the intended pattern for wrapping DB calls.
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];
    res.json(users);
  } catch (cause) {
    throw new DatabaseError('Failed to retrieve users', 'DB_FETCH_USERS_FAILED', cause);
  }
});

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 * Demonstrates: ValidationError (non-numeric id) and NotFoundError (unknown id).
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError(
      `'id' must be a positive integer, received: ${req.params.id}`,
      'INVALID_USER_ID',
    );
  }

  // Simulated in-memory store.
  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'USER_NOT_FOUND');
  }

  res.json(user);
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must come after all valid routes)
// ---------------------------------------------------------------------------

/**
 * Convert any request that reached this point without a matching route into a
 * NotFoundError so the central error handler can format it consistently.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`, 'ROUTE_NOT_FOUND'));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * Express recognises a four-argument middleware as an error handler.
 * All errors thrown by routes (or passed via next(err)) land here.
 *
 * Behaviour
 * ─────────
 * • Operational errors   → use the error's own statusCode + code + message.
 * • Non-operational errors (e.g. DatabaseError, unexpected crashes) → 500/503
 *   with a generic message so internal details are never leaked to callers.
 * • ValidationError      → the `details` array is forwarded when present.
 * • Stack traces are printed to stderr in development; suppressed in production.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Logging ──────────────────────────────────────────────────────────────
  // Always log the full error server-side.
  // Use `err.cause` (DatabaseError) to get the root cause if present.
  const rootCause = err.cause ? `\nCaused by: ${err.cause.stack ?? err.cause}` : '';

  if (process.env.NODE_ENV !== 'production') {
    console.error(`[${new Date().toISOString()}] ${err.stack}${rootCause}`);
  } else {
    // In production keep logs, but without the full stack trace in stdout.
    console.error(
      `[${new Date().toISOString()}] ${err.name}: ${err.message} | code=${err.code ?? 'UNKNOWN'}`,
    );
  }

  // ── Determine response shape ──────────────────────────────────────────────
  const isAppError = err instanceof AppError;

  // If the error is not one of our AppError subclasses, treat it as an
  // unexpected server error and hide the details from the client.
  const statusCode = isAppError ? err.statusCode : 500;

  const body = {
    error: {
      code:    isAppError ? err.code    : 'INTERNAL_SERVER_ERROR',
      message: isAppError && err.isOperational
        ? err.message
        : 'An unexpected error occurred. Please try again later.',
    },
  };

  // Attach validation details when present.
  if (err instanceof ValidationError && Array.isArray(err.details) && err.details.length > 0) {
    body.error.details = err.details;
  }

  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

