/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Each class extends the built-in Error and carries:
 *  - statusCode  – the HTTP status code sent to the client
 *  - code        – a stable machine-readable string (useful for clients / logs)
 *  - isOperational – distinguishes expected "safe" errors from unexpected bugs
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description.
   * @param {number}  statusCode    - HTTP status code (e.g. 404, 422, 500).
   * @param {string}  code          - Machine-readable error code.
   * @param {boolean} isOperational - true  → known/expected error (safe to expose).
   *                                  false → programmer error (hide details in prod).
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Keep the prototype chain intact so `instanceof` checks work correctly
    // after TypeScript / Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = new.target.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /**
   * Serialise the error to a plain object suitable for JSON responses.
   * Sensitive internals (stack, isOperational) are intentionally omitted.
   */
  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
        status:  this.statusCode,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – resource not found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [message]  - Defaults to a generic "not found" phrase.
   * @param {string} [resource] - Optional resource name, e.g. "User".
   *
   * @example
   *   throw new NotFoundError('User not found', 'User');
   *   throw new NotFoundError(); // → "Resource not found"
   */
  constructor(message, resource) {
    const resolvedMessage = message
      || (resource ? `${resource} not found` : 'Resource not found');

    super(resolvedMessage, 404, 'NOT_FOUND');

    // Optional: expose which resource type was missing.
    if (resource) this.resource = resource;
  }
}

// ---------------------------------------------------------------------------
// 422 – semantic / input validation failure
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}   [message] - Summary message. Defaults to "Validation failed".
   * @param {Object[]} [errors]  - Structured list of per-field validation errors.
   *   Each entry: { field: string, message: string }
   *
   * @example
   *   throw new ValidationError('Invalid payload', [
   *     { field: 'email', message: 'Must be a valid email address' },
   *     { field: 'age',   message: 'Must be a positive integer' },
   *   ]);
   */
  constructor(message = 'Validation failed', errors = []) {
    super(message, 422, 'VALIDATION_ERROR');

    // Normalise: always an array, even when a single string is passed.
    this.errors = Array.isArray(errors) ? errors : [{ message: errors }];
  }

  /** Override toJSON to include the per-field error list. */
  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
        status:  this.statusCode,
        errors:  this.errors,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 503 – database / data-layer failure
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]  - Human-readable summary.
   * @param {Error}  [original] - The underlying driver / query error.
   *                              Stored but NEVER forwarded to the client.
   *
   * @example
   *   try {
   *     await db.query(sql);
   *   } catch (err) {
   *     throw new DatabaseError('Failed to fetch users', err);
   *   }
   */
  constructor(message = 'A database error occurred', original) {
    // isOperational = false → treated as unexpected; generic message in prod.
    super(message, 503, 'DATABASE_ERROR', false);

    // Preserve the original driver error for internal logging only.
    if (original instanceof Error) {
      this.original = original;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 *  1. Route handlers throw (or next()) an AppError subclass.
 *  2. The 404 catch-all converts unknown routes into a NotFoundError.
 *  3. errorHandler() is the single place that writes every error response.
 */

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ── Body parsing ────────────────────────────────────────────────────────────
app.use(express.json());

// ── Simulated data store (in-memory) ────────────────────────────────────────
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Wraps an async route handler so that any rejected promise is forwarded
 * to Express's next(err) automatically — no try/catch boilerplate needed.
 *
 * @param {Function} fn - async (req, res, next) => …
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Simple liveness probe — no error paths needed here.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns every user.
 * Throws DatabaseError when the data layer is unavailable.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // Simulate a data-layer call that could reject.
  const rows = await fetchAllUsers();
  res.json(rows);
}));

/**
 * GET /users/:id
 * Returns a single user by id.
 * Throws ValidationError for a non-numeric id.
 * Throws NotFoundError when no matching record exists.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Validation failed', [
      { field: 'id', message: 'id must be a positive integer' },
    ]);
  }

  const user = await fetchUserById(id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'User');
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 * Throws ValidationError when required fields are absent or malformed.
 * Throws DatabaseError when the insert fails.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body ?? {};

  const fieldErrors = [];
  if (!name  || typeof name  !== 'string' || name.trim()  === '') {
    fieldErrors.push({ field: 'name',  message: 'name is required and must be a non-empty string' });
  }
  if (!email || typeof email !== 'string' || !email.includes('@')) {
    fieldErrors.push({ field: 'email', message: 'email is required and must be a valid email address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid user payload', fieldErrors);
  }

  const newUser = await createUser({ name: name.trim(), email: email.trim() });
  res.status(201).json(newUser);
}));

// ── 404 catch-all (must come after all real routes) ──────────────────────────

app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`));
});

// ── Centralised error-handling middleware ─────────────────────────────────────
// Express identifies this as error-handling middleware via its 4-argument signature.

/**
 * Determines whether to expose error details to the client.
 *
 * - Operational errors (NotFoundError, ValidationError, …) carry their own
 *   message because they are expected and safe.
 * - Non-operational errors (DatabaseError, unexpected throws) fall back to a
 *   generic message so implementation details are never leaked.
 *
 * The full error — including stack — is always logged server-side.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Always log the full error internally ────────────────────────────────
  const statusCode = err.statusCode ?? 500;
  console.error({
    code:       err.code    ?? 'INTERNAL_ERROR',
    statusCode,
    message:    err.message,
    // Include the original driver error when present (e.g. DatabaseError)
    original:   err.original?.message,
    stack:      err.stack,
    request: {
      method: req.method,
      url:    req.originalUrl,
      body:   req.body,
    },
  });

  // ── 2. Build the client response ───────────────────────────────────────────
  if (err instanceof AppError) {
    // Operational errors: use the structured toJSON() representation.
    // Non-operational AppErrors: replace the message with a safe generic text
    // so stack traces / internal details are never sent to the client.
    if (!err.isOperational) {
      err.message = 'An unexpected error occurred. Please try again later.';
    }

    return res.status(statusCode).json(err.toJSON());
  }

  // ── 3. Catch-all for completely unexpected errors (bugs, third-party throws)
  return res.status(500).json({
    error: {
      code:    'INTERNAL_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
      status:  500,
    },
  });
});

// ── Simulated data-layer functions ───────────────────────────────────────────
// In a real app these would call a DB driver (pg, mongoose, etc.).
// They are kept here to keep this file self-contained and testable.

async function fetchAllUsers() {
  try {
    // Simulates a DB round-trip; replace with real query.
    return users;
  } catch (err) {
    throw new DatabaseError('Failed to retrieve users', err);
  }
}

async function fetchUserById(id) {
  try {
    return users.find((u) => u.id === id) ?? null;
  } catch (err) {
    throw new DatabaseError(`Failed to retrieve user with id ${id}`, err);
  }
}

async function createUser({ name, email }) {
  try {
    const newUser = { id: users.length + 1, name, email };
    users.push(newUser);
    return newUser;
  } catch (err) {
    throw new DatabaseError('Failed to create user', err);
  }
}

// ── Server bootstrap (skipped when file is required by tests) ─────────────────

if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

