/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * All classes extend AppError, which itself extends the native Error so that:
 *  - instanceof checks work correctly throughout the codebase.
 *  - Every error carries a consistent { statusCode, code, message } shape.
 *  - The centralised error-handling middleware can rely on a single contract.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

/**
 * AppError — the root of every operational error in this application.
 *
 * @param {string}  message     - Human-readable description of the error.
 * @param {number}  statusCode  - HTTP status code to send to the client.
 * @param {string}  code        - Machine-readable error code (e.g. "NOT_FOUND").
 * @param {object}  [meta={}]   - Optional extra context (field names, IDs, …).
 */
class AppError extends Error {
  constructor(message, statusCode, code, meta = {}) {
    super(message);

    // Restore the prototype chain broken by extending built-ins in ES5-compiled
    // environments (safe no-op in native ES2015+).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name; // e.g. "NotFoundError"
    this.statusCode = statusCode;
    this.code       = code;
    this.meta       = meta;

    // Marks this as an "expected" operational error (not a programmer mistake).
    // The error middleware uses this flag to decide log verbosity.
    this.isOperational = true;

    // Capture a clean stack trace that starts at the call-site, not inside
    // this constructor.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise to the JSON shape the error middleware sends to clients.
   * Override in subclasses to add extra fields.
   */
  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
        ...(Object.keys(this.meta).length > 0 && { details: this.meta }),
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

/**
 * NotFoundError — raised when a requested resource does not exist.
 *
 * HTTP 404
 *
 * @example
 *   throw new NotFoundError('User', 42);
 *   // → { error: { code: 'NOT_FOUND', message: 'User with id 42 was not found.' } }
 *
 * @param {string}        resource  - Name of the resource type (e.g. "User").
 * @param {string|number} [id]      - Optional identifier that was looked up.
 */
class NotFoundError extends AppError {
  constructor(resource = 'Resource', id) {
    const message = id !== undefined
      ? `${resource} with id ${id} was not found.`
      : `${resource} was not found.`;

    super(message, 404, 'NOT_FOUND', id !== undefined ? { resource, id } : { resource });
  }
}

// ---------------------------------------------------------------------------
// 422 Validation Error
// ---------------------------------------------------------------------------

/**
 * ValidationError — raised when incoming data fails business-rule or
 * schema validation.
 *
 * HTTP 422 Unprocessable Entity
 *
 * @example
 *   throw new ValidationError('Invalid email address.', [
 *     { field: 'email', message: 'Must be a valid email.' },
 *   ]);
 *
 * @param {string}   message          - Summary of what failed.
 * @param {Array}    [errors=[]]      - Per-field error objects  { field, message }.
 */
class ValidationError extends AppError {
  constructor(message = 'Validation failed.', errors = []) {
    super(message, 422, 'VALIDATION_ERROR', { errors });
    this.errors = errors; // convenience shorthand
  }

  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
        ...(this.errors.length > 0 && { errors: this.errors }),
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 503 Database Error
// ---------------------------------------------------------------------------

/**
 * DatabaseError — raised when an interaction with the database fails.
 *
 * HTTP 503 Service Unavailable
 *
 * Internally we attach the original cause so it can be logged server-side,
 * but we never expose raw DB messages in the JSON response.
 *
 * @example
 *   try { await db.query(sql); }
 *   catch (cause) { throw new DatabaseError('Could not fetch users.', cause); }
 *
 * @param {string} message    - Safe, user-facing description.
 * @param {Error}  [cause]    - The original low-level error (logged, not exposed).
 */
class DatabaseError extends AppError {
  constructor(message = 'A database error occurred.', cause) {
    super(message, 503, 'DATABASE_ERROR');

    // Node 16.9+ native cause support, plus our own reference for older runtimes.
    if (cause) {
      this.cause = cause;
    }
  }

  toJSON() {
    // Deliberately omit `cause` — never leak raw DB errors to clients.
    return {
      error: {
        code:    this.code,
        message: this.message,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * Express application — refactored to use centralised error handling.
 *
 * Key changes
 * ───────────
 * • All route-level errors are thrown (or passed to next()) instead of being
 *   handled inline with res.status().json().
 * • A single errorHandler middleware at the bottom of the stack owns every
 *   error response, ensuring a consistent JSON shape across the whole API.
 * • Custom error classes (NotFoundError, ValidationError, DatabaseError) from
 *   errors.js are used so that each throw site is expressive and self-
 *   documenting.
 * • Unhandled promise rejections inside async route handlers are caught by the
 *   asyncHandler wrapper and forwarded to the error middleware via next().
 */

'use strict';

const express = require('express');

const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Request parsing
// ---------------------------------------------------------------------------

app.use(express.json());

// ---------------------------------------------------------------------------
// Utility: async route wrapper
// ---------------------------------------------------------------------------

/**
 * asyncHandler
 * Wraps an async route handler so that any rejected promise (or thrown error)
 * is automatically forwarded to Express's error pipeline via next(err).
 *
 * Usage:
 *   app.get('/path', asyncHandler(async (req, res) => { … }));
 *
 * Without this wrapper, an unhandled rejection inside an async handler would
 * silently hang the request (Express < 5) instead of reaching errorHandler.
 *
 * @param   {Function} fn  - Async route handler (req, res, next) => Promise
 * @returns {Function}     - Standard Express middleware
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Basic liveness probe — always returns 200 while the process is alive.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns a list of all users.
 *
 * Throws:
 *  - DatabaseError  if the data layer is unavailable.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // Simulate data-layer call. In a real app this would be something like:
  //   const users = await UserRepository.findAll();
  // Any low-level DB exception should be caught and re-thrown as DatabaseError:
  //   try { … } catch (cause) { throw new DatabaseError('Could not fetch users.', cause); }
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  res.json(users);
}));

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 *
 * Throws:
 *  - ValidationError  if :id is not a positive integer.
 *  - NotFoundError    if no user with that ID exists.
 *  - DatabaseError    if the data layer is unavailable.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user ID.', [
      { field: 'id', message: 'id must be a positive integer.' },
    ]);
  }

  // Simulate data-layer call.
  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];

  if (!user) {
    throw new NotFoundError('User', id);
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 *
 * Expected body: { name: string, email: string }
 *
 * Throws:
 *  - ValidationError  if required fields are missing or malformed.
 *  - DatabaseError    if the data layer is unavailable.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'name is required and must be a non-empty string.' });
  }

  if (!email || typeof email !== 'string') {
    fieldErrors.push({ field: 'email', message: 'email is required.' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'email must be a valid email address.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Request body contains invalid fields.', fieldErrors);
  }

  // Simulate successful creation.
  const newUser = { id: 3, name: name.trim(), email };
  res.status(201).json(newUser);
}));

// ---------------------------------------------------------------------------
// 404 catch-all — must come AFTER all valid routes
// ---------------------------------------------------------------------------

/**
 * Any request that reaches this handler did not match a defined route.
 * We throw a NotFoundError so it flows through the same errorHandler as
 * every other error, keeping the response shape uniform.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path}`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Express identifies this as an error handler because it declares four
 * parameters (err, req, res, next).  It MUST be registered after all routes
 * and other middleware.
 *
 * Responsibilities:
 *  1. Determine whether the error is one of our known AppError subclasses
 *     (operational) or an unexpected programmer error.
 *  2. Log the error with an appropriate severity level.
 *  3. Send a consistent JSON error response to the client.
 *  4. Never leak internal stack traces or raw database messages to clients.
 *
 * Response shape (always):
 *  {
 *    "error": {
 *      "code":     "MACHINE_READABLE_CODE",
 *      "message":  "Human-readable summary.",
 *      "errors":   [ { "field": "…", "message": "…" } ]  // ValidationError only
 *      "details":  { … }                                  // when meta is present
 *    }
 *  }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Operational errors (thrown deliberately by our own code) ──────────────
  if (err instanceof AppError && err.isOperational) {
    // Log at a lower severity — these are expected conditions, not bugs.
    console.warn(
      `[${err.code}] ${req.method} ${req.path} → ${err.statusCode}: ${err.message}`,
    );

    return res.status(err.statusCode).json(err.toJSON());
  }

  // ── Unexpected / programmer errors ────────────────────────────────────────
  // Log the full stack so we can investigate, but send a generic 500 to the
  // client — never expose internal details.
  console.error('Unhandled error:', err);

  return res.status(500).json({
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

