const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// ── AppError ────────────────────────────────────────────────────────────────
const base = new AppError('base msg', 400, 'BASE_CODE', { foo: 'bar' });
console.assert(base instanceof Error,    'AppError extends Error');
console.assert(base instanceof AppError, 'AppError instanceof itself');
console.assert(base.statusCode === 400,  'AppError.statusCode');
console.assert(base.code === 'BASE_CODE','AppError.code');
console.assert(base.isOperational,       'AppError.isOperational');
console.assert(base.name === 'AppError', 'AppError.name');
const baseJSON = base.toJSON();
console.assert(baseJSON.error.code === 'BASE_CODE',    'AppError.toJSON code');
console.assert(baseJSON.error.message === 'base msg',  'AppError.toJSON message');
console.assert(baseJSON.error.details.foo === 'bar',   'AppError.toJSON details');
console.log('AppError ✓');

// ── NotFoundError ───────────────────────────────────────────────────────────
const nf1 = new NotFoundError('User', 42);
console.assert(nf1 instanceof AppError,       'NotFoundError extends AppError');
console.assert(nf1 instanceof NotFoundError,  'NotFoundError instanceof itself');
console.assert(nf1.statusCode === 404,         'NotFoundError.statusCode');
console.assert(nf1.code === 'NOT_FOUND',       'NotFoundError.code');
console.assert(nf1.message.includes('42'),     'NotFoundError.message includes id');
console.assert(nf1.isOperational,              'NotFoundError.isOperational');
const nf1JSON = nf1.toJSON();
console.assert(nf1JSON.error.details.id === 42,'NotFoundError.toJSON details.id');

const nf2 = new NotFoundError('Config');
console.assert(nf2.message === 'Config was not found.', 'NotFoundError no-id message');
const nf2JSON = nf2.toJSON();
console.assert(!nf2JSON.error.details?.id,     'NotFoundError no-id has no id in details');
console.log('NotFoundError ✓');

// ── ValidationError ─────────────────────────────────────────────────────────
const ve = new ValidationError('Bad input', [
  { field: 'email', message: 'Invalid email.' },
]);
console.assert(ve instanceof AppError,          'ValidationError extends AppError');
console.assert(ve instanceof ValidationError,   'ValidationError instanceof itself');
console.assert(ve.statusCode === 422,           'ValidationError.statusCode');
console.assert(ve.code === 'VALIDATION_ERROR',  'ValidationError.code');
console.assert(ve.errors.length === 1,          'ValidationError.errors');
const veJSON = ve.toJSON();
console.assert(veJSON.error.errors[0].field === 'email', 'ValidationError.toJSON errors[0].field');

const veEmpty = new ValidationError();
console.assert(veEmpty.message === 'Validation failed.','ValidationError default message');
console.assert(!veEmpty.toJSON().error.errors,           'ValidationError empty errors omitted');
console.log('ValidationError ✓');

// ── DatabaseError ────────────────────────────────────────────────────────────
const cause = new Error('pg: connection refused');
const de = new DatabaseError('Could not fetch users.', cause);
console.assert(de instanceof AppError,        'DatabaseError extends AppError');
console.assert(de instanceof DatabaseError,   'DatabaseError instanceof itself');
console.assert(de.statusCode === 503,         'DatabaseError.statusCode');
console.assert(de.code === 'DATABASE_ERROR',  'DatabaseError.code');
console.assert(de.cause === cause,            'DatabaseError.cause stored');
const deJSON = de.toJSON();
console.assert(!deJSON.error.cause,           'DatabaseError.toJSON hides cause');
console.assert(!deJSON.error.details,         'DatabaseError.toJSON hides details');

const deDefault = new DatabaseError();
console.assert(deDefault.message === 'A database error occurred.', 'DatabaseError default message');
console.log('DatabaseError ✓');

console.log('\nAll errors.js assertions passed ✓');
"

