// Requires express to be available; if not, skip gracefully
let app;
try { app = require('./app'); } catch(e) { console.log('express not installed – skipping route tests:', e.message); process.exit(0); }

const http = require('http');

const server = app.listen(0, async () => {
  const { port } = server.address();
  const base = \`http://localhost:\${port}\`;

  const get  = (path) => fetch(\`\${base}\${path}\`);
  const post = (path, body) => fetch(\`\${base}\${path}\`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });

  let passed = 0;
  const ok = (label) => { console.log(\`  ✓ \${label}\`); passed++; };
  const fail = (label, detail) => { console.error(\`  ✗ \${label}: \${detail}\`); process.exitCode = 1; };

  try {
    // GET /health
    {
      const r = await get('/health');
      const j = await r.json();
      r.status === 200 && j.status === 'ok' ? ok('GET /health 200') : fail('GET /health', JSON.stringify(j));
    }

    // GET /users
    {
      const r = await get('/users');
      const j = await r.json();
      r.status === 200 && Array.isArray(j) && j.length === 2 ? ok('GET /users 200') : fail('GET /users', JSON.stringify(j));
    }

    // GET /users/:id — found
    {
      const r = await get('/users/1');
      const j = await r.json();
      r.status === 200 && j.name === 'Alice' ? ok('GET /users/1 200') : fail('GET /users/1', JSON.stringify(j));
    }

    // GET /users/:id — not found → 404 NOT_FOUND
    {
      const r = await get('/users/999');
      const j = await r.json();
      r.status === 404 && j.error?.code === 'NOT_FOUND' ? ok('GET /users/999 → 404 NOT_FOUND') : fail('GET /users/999', JSON.stringify(j));
    }

    // GET /users/:id — bad id → 422 VALIDATION_ERROR
    {
      const r = await get('/users/abc');
      const j = await r.json();
      r.status === 422 && j.error?.code === 'VALIDATION_ERROR' ? ok('GET /users/abc → 422 VALIDATION_ERROR') : fail('GET /users/abc', JSON.stringify(j));
    }

    // GET /users/:id — negative id → 422 VALIDATION_ERROR
    {
      const r = await get('/users/-5');
      const j = await r.json();
      r.status === 422 && j.error?.code === 'VALIDATION_ERROR' ? ok('GET /users/-5 → 422 VALIDATION_ERROR') : fail('GET /users/-5', JSON.stringify(j));
    }

    // POST /users — valid
    {
      const r = await post('/users', { name: 'Carol', email: 'carol@example.com' });
      const j = await r.json();
      r.status === 201 && j.name === 'Carol' ? ok('POST /users 201') : fail('POST /users valid', JSON.stringify(j));
    }

    // POST /users — missing fields → 422 VALIDATION_ERROR
    {
      const r = await post('/users', {});
      const j = await r.json();
      r.status === 422 && j.error?.code === 'VALIDATION_ERROR' && j.error?.errors?.length === 2
        ? ok('POST /users missing fields → 422')
        : fail('POST /users missing fields', JSON.stringify(j));
    }

    // POST /users — bad email → 422 VALIDATION_ERROR
    {
      const r = await post('/users', { name: 'Dave', email: 'not-an-email' });
      const j = await r.json();
      r.status === 422 && j.error?.code === 'VALIDATION_ERROR'
        ? ok('POST /users bad email → 422')
        : fail('POST /users bad email', JSON.stringify(j));
    }

    // Unknown route → 404 NOT_FOUND
    {
      const r = await get('/does-not-exist');
      const j = await r.json();
      r.status === 404 && j.error?.code === 'NOT_FOUND' ? ok('GET /does-not-exist → 404 NOT_FOUND') : fail('GET /does-not-exist', JSON.stringify(j));
    }

    // Error shape never leaks stack traces
    {
      const r = await get('/users/999');
      const j = await r.json();
      const raw = JSON.stringify(j);
      !raw.includes('at ') ? ok('No stack trace in error response') : fail('stack trace leaked', raw);
    }

    console.log(\`\nAll \${passed} route integration tests passed ✓\`);
  } finally {
    server.close();
  }
});
