/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error so that:
 *  - instanceof checks work correctly throughout the codebase.
 *  - Stack traces are captured automatically via Error.captureStackTrace.
 *  - The centralised error-handling middleware can branch solely on type /
 *    the `statusCode` property, keeping route handlers clean.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError
 *
 * Abstract base class for all application-level errors.
 * Not intended to be thrown directly; use one of the concrete subclasses.
 *
 * @property {number}  statusCode - HTTP status code sent to the client.
 * @property {string}  code       - Machine-readable error identifier.
 * @property {boolean} isOperational - true  → known, expected error (safe to
 *                                              surface to the client).
 *                                     false → programmer / unexpected error
 *                                              (the middleware will hide the
 *                                              details from the client).
 */
class AppError extends Error {
  /**
   * @param {string} message      - Human-readable description.
   * @param {number} statusCode   - HTTP status code (e.g. 400, 404, 500).
   * @param {string} code         - Short, uppercase snake_case identifier
   *                                (e.g. 'NOT_FOUND', 'VALIDATION_ERROR').
   * @param {boolean} [isOperational=true]
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain the correct prototype chain when targeting ES5 output.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name = new.target.name;
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /**
   * Returns a plain-object representation safe for JSON serialisation.
   * The middleware uses this to build the response body.
   *
   * @returns {{ error: { code: string, message: string } }}
   */
  toJSON() {
    return {
      error: {
        code: this.code,
        message: this.message,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// Concrete error classes
// ---------------------------------------------------------------------------

/**
 * NotFoundError  (404)
 *
 * Raised when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   // → 404  { error: { code: 'USER_NOT_FOUND', message: 'User not found' } }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {string} [code='NOT_FOUND']
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

/**
 * ValidationError  (400)
 *
 * Raised when the caller supplies invalid or missing input data.
 * Optionally carries a `details` array so individual field errors can be
 * returned in a single response.
 *
 * @example
 *   throw new ValidationError('Invalid request body', 'INVALID_BODY', [
 *     { field: 'email', message: 'Must be a valid e-mail address' },
 *   ]);
 *   // → 400 {
 *   //     error: {
 *   //       code: 'INVALID_BODY',
 *   //       message: 'Invalid request body',
 *   //       details: [{ field: 'email', message: '...' }]
 *   //     }
 *   //   }
 */
class ValidationError extends AppError {
  /**
   * @param {string}   [message='Validation failed']
   * @param {string}   [code='VALIDATION_ERROR']
   * @param {Array<{ field?: string, message: string }>} [details=[]]
   */
  constructor(message = 'Validation failed', code = 'VALIDATION_ERROR', details = []) {
    super(message, 400, code);
    /** @type {Array<{ field?: string, message: string }>} */
    this.details = details;
  }

  /** @override – includes `details` in the serialised body. */
  toJSON() {
    const base = super.toJSON();
    if (this.details.length > 0) {
      base.error.details = this.details;
    }
    return base;
  }
}

/**
 * DatabaseError  (503)
 *
 * Raised when an underlying storage operation fails unexpectedly.
 * Marked as non-operational (isOperational = false) by default so that the
 * error middleware knows to hide the raw DB message from external clients
 * and log it server-side only.
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted', 'DB_POOL_EXHAUSTED');
 *   // → 503  { error: { code: 'SERVICE_UNAVAILABLE',
 *   //                   message: 'A database error occurred' } }
 *   // (the real message is only visible in server logs)
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {string} [code='DATABASE_ERROR']
   * @param {Error|null} [originalError=null] - The raw error from the DB driver,
   *        kept on the instance for logging but never sent to the client.
   */
  constructor(
    message = 'A database error occurred',
    code = 'DATABASE_ERROR',
    originalError = null,
  ) {
    // isOperational = false → internal details are hidden from the client.
    super(message, 503, code, false);
    /** @type {Error|null} */
    this.originalError = originalError;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 *
 * Express application.
 *
 * Error-handling strategy
 * ───────────────────────
 * Route handlers and middleware must NOT call res.status().json() for error
 * cases.  Instead they should:
 *
 *   • throw an AppError subclass (synchronous handlers), or
 *   • call next(error)           (asynchronous handlers / callbacks).
 *
 * Every thrown/forwarded error ends up in the single centralised error handler
 * registered at the bottom of this file, which guarantees a consistent JSON
 * error shape and a single place to add logging, alerting, etc.
 */

const express = require('express');

const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

// ─── Request parsing ────────────────────────────────────────────────────────

app.use(express.json());

// ─── Routes ─────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Simple liveness probe. Returns the current server time.
 * No failure path — always succeeds unless the process itself is broken.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns the full list of users.
 *
 * Query parameters
 *   ?limit  (optional) – Maximum number of records to return (1 – 100).
 *                        Throws ValidationError when the value is out of range.
 *
 * Demonstrates: ValidationError
 */
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Optional ?limit query param — validate it when present.
  if (req.query.limit !== undefined) {
    const limit = Number(req.query.limit);

    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new ValidationError(
        'Query parameter "limit" must be an integer between 1 and 100.',
        'INVALID_QUERY_PARAM',
        [{ field: 'limit', message: 'Must be an integer between 1 and 100.' }],
      );
    }

    return res.json(users.slice(0, limit));
  }

  res.json(users);
});

/**
 * GET /users/:id
 *
 * Returns a single user by numeric ID.
 *
 * Demonstrates: ValidationError (non-numeric id), NotFoundError (unknown id)
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError(
      `User ID must be a positive integer, received: "${req.params.id}".`,
      'INVALID_USER_ID',
      [{ field: 'id', message: 'Must be a positive integer.' }],
    );
  }

  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];

  if (!user) {
    throw new NotFoundError(`User with ID ${id} not found.`, 'USER_NOT_FOUND');
  }

  res.json(user);
});

/**
 * POST /users
 *
 * Creates a new user.  Expects { name, email } in the request body.
 *
 * Demonstrates: ValidationError (missing/invalid fields), DatabaseError
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string.' });
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'A valid e-mail address is required.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid user payload.', 'INVALID_USER_PAYLOAD', fieldErrors);
  }

  // Simulate a transient DB write failure so DatabaseError handling is
  // exercised.  In a real app this try/catch would wrap an actual DB call.
  try {
    simulateDatabaseWrite({ name: name.trim(), email: email.trim() });
  } catch (dbErr) {
    throw new DatabaseError(
      'Unable to save the new user. Please try again later.',
      'USER_CREATE_FAILED',
      dbErr,                  // stored as originalError for server-side logging
    );
  }

  res.status(201).json({ id: 3, name: name.trim(), email: email.trim() });
});

/**
 * DELETE /users/:id
 *
 * Deletes a user by ID.
 *
 * Demonstrates: NotFoundError
 */
app.delete('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError(
      `User ID must be a positive integer, received: "${req.params.id}".`,
      'INVALID_USER_ID',
      [{ field: 'id', message: 'Must be a positive integer.' }],
    );
  }

  const existingIds = new Set([1, 2]);

  if (!existingIds.has(id)) {
    throw new NotFoundError(`User with ID ${id} not found.`, 'USER_NOT_FOUND');
  }

  res.status(204).send();
});

// ─── 404 catch-all ──────────────────────────────────────────────────────────

/**
 * Catch-all for any route that was not matched above.
 * Must be registered AFTER all valid routes.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found.`, 'ROUTE_NOT_FOUND'));
});

// ─── Centralised error-handling middleware ───────────────────────────────────

/**
 * errorHandler
 *
 * Single, authoritative error handler for the entire application.
 *
 * Behaviour
 * ─────────
 * • Operational errors (AppError subclasses with isOperational = true):
 *     → Serialise via error.toJSON() and respond with error.statusCode.
 *
 * • Non-operational errors (DatabaseError, unexpected throws, etc.):
 *     → Log the full error server-side (stack + originalError when present).
 *     → Respond with a safe 503 / 500 body that does NOT leak internals.
 *
 * • Express's built-in body-parser errors (SyntaxError with status 400):
 *     → Converted to a ValidationError-shaped 400 response.
 *
 * The function signature must have exactly four parameters so Express
 * recognises it as an error-handling middleware.
 *
 * @param {Error}               err
 * @param {express.Request}     req
 * @param {express.Response}    res
 * @param {express.NextFunction} next  - Required by Express; unused here.
 */
// eslint-disable-next-line no-unused-vars
function errorHandler(err, req, res, next) {
  // ── 1. Normalise Express / third-party errors ──────────────────────────

  // Body-parser sends a SyntaxError with a `status` property of 400 when
  // the request body is malformed JSON.
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: {
        code: 'MALFORMED_JSON',
        message: 'Request body contains malformed JSON.',
      },
    });
  }

  // ── 2. Operational AppError (NotFoundError, ValidationError, …) ────────

  if (err instanceof AppError && err.isOperational) {
    return res.status(err.statusCode).json(err.toJSON());
  }

  // ── 3. Non-operational / unexpected errors ─────────────────────────────

  // Always log the full error so it can be investigated.
  // Replace console.error with your preferred logger (Winston, Pino, etc.).
  console.error('[errorHandler] Unhandled error:', {
    message:       err.message,
    stack:         err.stack,
    originalError: err.originalError ?? null,   // DatabaseError enrichment
    path:          req.path,
    method:        req.method,
  });

  // Determine the status code: use what the error already declares (e.g.
  // DatabaseError uses 503) or fall back to 500 for unknown errors.
  const statusCode = (err instanceof AppError) ? err.statusCode : 500;

  return res.status(statusCode).json({
    error: {
      code:    statusCode === 503 ? 'SERVICE_UNAVAILABLE' : 'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
}

app.use(errorHandler);

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * simulateDatabaseWrite
 *
 * Stand-in for a real database call. Throws a raw Error to exercise the
 * DatabaseError wrapping in the POST /users handler.
 *
 * @param {{ name: string, email: string }} _payload - ignored
 * @throws {Error} Always — replace with a real DB call in production.
 */
function simulateDatabaseWrite(_payload) {
  // Uncomment the line below to let the route succeed for manual testing:
  // return { id: 3, ..._payload };
  throw new Error('ECONNRESET: DB connection lost during write');
}

// ─── Start server (skipped when file is required by tests) ───────────────────

if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

