'use strict';
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let failures = 0;
function assert(label, condition) {
  if (condition) { console.log('  ✓', label); }
  else           { console.error('  ✗', label); failures++; }
}

// ─ AppError (abstract base) ─────────────────────────────────────────────
const base = new AppError('base msg', 418, 'TEAPOT');
assert('AppError instanceof Error',        base instanceof Error);
