/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the native Error so that:
 *  - instanceof checks work as expected
 *  - Stack traces are captured correctly
 *  - The error middleware can branch on type without fragile string matching
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError
 *
 * All custom errors inherit from this class.
 * It adds two properties that the error-handling middleware relies on:
 *
 *   statusCode  – the HTTP status code to send to the client
 *   isOperational – true  → a known, expected error (safe to expose details)
 *                   false → a programming error (swallow details in prod)
 */
class AppError extends Error {
  /**
   * @param {string}  message     Human-readable description.
   * @param {number}  statusCode  HTTP status code (default 500).
   * @param {boolean} isOperational Whether this is an expected operational
   *                               error (default true).
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);

    // Keep the prototype chain intact so `instanceof` works after transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name       = this.constructor.name;
    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Captures a clean stack trace that starts at the call site, not inside
    // this constructor.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * NotFoundError
 *
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found');
 *   // → 404  { error: 'Not Found', message: 'User not found' }
 *
 * @example
 *   throw new NotFoundError();
 *   // → 404  { error: 'Not Found', message: 'Resource not found' }
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {string} [resource]  Optional resource name for richer messages,
   *                             e.g. 'User', 'Product'.
   */
  constructor(message = 'Resource not found', resource = null) {
    super(message, 404);
    this.resource = resource;
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * ValidationError
 *
 * Thrown when user-supplied input fails validation checks.
 * Carries an optional `fields` map so clients can highlight individual fields.
 *
 * @example
 *   throw new ValidationError('Invalid request body');
 *
 * @example
 *   throw new ValidationError('Validation failed', {
 *     email: 'Must be a valid email address',
 *     age:   'Must be a positive integer',
 *   });
 *   // → 422  { error: 'Validation Error', message: '…', fields: { … } }
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message='Validation failed']
   * @param {Object} [fields={}]  Key → error-message map for field-level errors.
   */
  constructor(message = 'Validation failed', fields = {}) {
    super(message, 422);
    this.fields = fields;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * DatabaseError
 *
 * Thrown when a database operation fails (connection error, query error, etc.).
 * Marked as *non-operational* by default because database failures are
 * unexpected at runtime; the middleware will therefore suppress the raw
 * message in production and log the full details server-side.
 *
 * @example
 *   throw new DatabaseError('Connection timed out', originalError);
 *   // → 503  { error: 'Service Unavailable', message: 'Database error' }
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {Error}  [cause=null]   The original low-level error for server logs.
   */
  constructor(message = 'A database error occurred', cause = null) {
    // isOperational = false → middleware will not expose the raw message to
    // clients in production.
    super(message, 503, false);
    // `cause` is part of the ES2022 Error spec; we also attach it manually
    // so it is accessible on older runtimes.
    if (cause) this.cause = cause;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 *  Route/middleware throws (or calls next(err))
 *    → errorHandler middleware formats and sends the response
 *    → unhandledRejection / uncaughtException safety nets log and exit
 */

'use strict';

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Built-in middleware
// ---------------------------------------------------------------------------

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe – never throws, always returns 200.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Demonstrates: happy path – no error thrown.
 */
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  res.json(users);
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Demonstrates:
 *   • ValidationError  – id is not a valid positive integer
 *   • NotFoundError    – id is valid but no user exists for it
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User ID must be a positive integer', {
      id: 'Must be a positive integer',
    });
  }

  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'User');
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 *
 * Demonstrates:
 *   • ValidationError  – required fields are absent or malformed
 *   • DatabaseError    – simulated persistence failure
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'Name is required and must be a non-empty string';
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    fieldErrors.email = 'A valid email address is required';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Invalid user data', fieldErrors);
  }

  // Simulate a database write that fails (remove / replace with real DB call).
  const dbAvailable = false; // toggle to true to simulate success
  if (!dbAvailable) {
    throw new DatabaseError(
      'Failed to persist user record',
      new Error('Connection refused by database host')
    );
  }

  // Simulated successful creation.
  res.status(201).json({ id: 3, name: name.trim(), email: email.trim() });
});

// ---------------------------------------------------------------------------
// 404 catch-all  (must come AFTER all real routes)
// ---------------------------------------------------------------------------

/**
 * Any request that reaches this handler matched no defined route.
 * We throw (via next) so the single errorHandler renders the response.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Express identifies this as an error-handling middleware because it declares
 * four parameters (err, req, res, next).  It must be the LAST app.use() call.
 *
 * Behaviour
 * ─────────
 *  • Operational errors (AppError subclasses with isOperational = true):
 *      Always surface the message and any extra context to the client.
 *
 *  • Non-operational errors (e.g. DatabaseError, plain Error, unexpected throws):
 *      Log full details server-side; send a generic message to the client in
 *      production so internal details are never leaked.
 *
 *  • Development mode:
 *      Always include the stack trace in the response for easier debugging.
 *
 * @param {Error}            err
 * @param {express.Request}  req
 * @param {express.Response} res
 * @param {Function}         next  – required by Express even if unused
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  // ------------------------------------------------------------------
  // 1. Log every error server-side (replace with your logger of choice)
  // ------------------------------------------------------------------
  console.error({
    timestamp:  new Date().toISOString(),
    method:     req.method,
    url:        req.originalUrl,
    error:      err.name ?? 'Error',
    message:    err.message,
    statusCode: err.statusCode,
    stack:      err.stack,
    ...(err.cause ? { cause: err.cause.message } : {}),
  });

  // ------------------------------------------------------------------
  // 2. Determine status code
  //    • AppError subclasses carry their own statusCode.
  //    • Anything else is an unexpected crash → 500.
  // ------------------------------------------------------------------
  const statusCode = err instanceof AppError ? err.statusCode : 500;

  // ------------------------------------------------------------------
  // 3. Build the response body
  // ------------------------------------------------------------------
  const isOperational = err instanceof AppError && err.isOperational;

  // Human-readable label for the error category.
  const errorLabel = resolveErrorLabel(statusCode);

  // Base payload always sent.
  const body = {
    error:   errorLabel,
    message: isOperational
      ? err.message
      : 'An unexpected error occurred. Please try again later.',
  };

  // Attach field-level errors for ValidationError.
  if (err instanceof ValidationError && Object.keys(err.fields ?? {}).length > 0) {
    body.fields = err.fields;
  }

  // Expose stack trace in development for any error type.
  if (isDev) {
    body.stack = err.stack;
    if (err.cause) body.cause = err.cause.message;
  }

  // ------------------------------------------------------------------
  // 4. Send the response
  // ------------------------------------------------------------------
  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Helper
// ---------------------------------------------------------------------------

/**
 * Maps an HTTP status code to a short, client-facing label.
 *
 * @param {number} statusCode
 * @returns {string}
 */
function resolveErrorLabel(statusCode) {
  const labels = {
    400: 'Bad Request',
    401: 'Unauthorised',
    403: 'Forbidden',
    404: 'Not Found',
    409: 'Conflict',
    422: 'Validation Error',
    429: 'Too Many Requests',
    500: 'Internal Server Error',
    503: 'Service Unavailable',
  };
  return labels[statusCode] ?? 'Error';
}

// ---------------------------------------------------------------------------
// Process-level safety nets
// ---------------------------------------------------------------------------

/**
 * Catch any Promise rejection that was never handled by a .catch() or
 * try/catch block.  Log it and exit so the process manager (PM2, Docker, etc.)
 * can restart cleanly instead of running in an unknown state.
 */
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled promise rejection:', reason);
  process.exit(1);
});

/**
 * Catch synchronous exceptions that escaped every try/catch.
 * Same reasoning as above – log and exit rather than continue in a
 * potentially corrupt state.
 */
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  process.exit(1);
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

