'use strict';
process.env.NODE_ENV = 'development';

// Minimal stubs so we can load app without a real Express listen()
const app = require('./app');
const { NotFoundError, ValidationError, DatabaseError } = require('./errors');

// ── Utility: simulate a request through the Express handler stack ──────────
function makeReq(method, path, body) {
  return { method, originalUrl: path, body: body ?? {}, params: {} };
}

function makeRes() {
  const res = { _status: null, _body: null };
  res.status  = (s) => { res._status = s; return res; };
  res.json    = (b) => { res._body   = b; return res; };
  return res;
}

// Find the error handler (4-arg middleware registered last)
const errorHandler = app._router.stack
  .filter(l => l.handle && l.handle.length === 4)
  .pop().handle;

function runErrorHandler(err) {
  const req  = makeReq('GET', '/test');
  const res  = makeRes();
  const next = () => {};
  errorHandler(err, req, res, next);
  return { status: res._status, body: res._body };
}

// ── NotFoundError ──────────────────────────────────────────────────────────
{
  const { status, body } = runErrorHandler(new NotFoundError('User 99 not found', 'User'));
  console.assert(status === 404,               'NotFoundError: wrong status');
  console.assert(body.error   === 'Not Found', 'NotFoundError: wrong error label');
  console.assert(body.message === 'User 99 not found', 'NotFoundError: wrong message');
  console.assert(typeof body.stack === 'string',       'NotFoundError: missing stack in dev');
  console.log('errorHandler / NotFoundError:   PASS');
}

// ── ValidationError ────────────────────────────────────────────────────────
{
  const { status, body } = runErrorHandler(
    new ValidationError('Bad input', { email: 'invalid email' })
  );
  console.assert(status === 422,                         'ValidationError: wrong status');
  console.assert(body.error   === 'Validation Error',    'ValidationError: wrong error label');
  console.assert(body.fields.email === 'invalid email',  'ValidationError: fields not forwarded');
  console.log('errorHandler / ValidationError: PASS');
}

// ── DatabaseError (non-operational) ───────────────────────────────────────
{
