'use strict';

// Disable the process-level safety-net handlers while running tests so they
// do not call process.exit(1) on assertion failures.
process.removeAllListeners('uncaughtException');
process.removeAllListeners('unhandledRejection');

process.env.NODE_ENV = 'development';

const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');
const app = require('./app');

let passed = 0;
let failed = 0;

function assert(condition, label) {
  if (condition) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}`);
    failed++;
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Locate the 4-arg error-handling middleware registered last on the app. */
function getErrorHandler() {
  return app._router.stack
    .filter(l => l.handle && l.handle.length === 4)
    .pop().handle;
}

/** Simulate the Express error-handler contract. */
function runErrorHandler(err) {
  const req  = { method: 'GET', originalUrl: '/test', body: {} };
  const res  = { _status: null, _body: null };
  res.status  = (s) => { res._status = s; return res; };
  res.json    = (b) => { res._body   = b; return res; };
  getErrorHandler()(err, req, res, () => {});
  return { status: res._status, body: res._body };
}

// ---------------------------------------------------------------------------
// 1. Error class unit tests
// ---------------------------------------------------------------------------
console.log('\n── Error class tests ─────────────────────────────────────────');

// NotFoundError
const nfe = new NotFoundError('User 99 not found', 'User');
assert(nfe instanceof Error,          'NotFoundError instanceof Error');
assert(nfe instanceof AppError,       'NotFoundError instanceof AppError');
assert(nfe instanceof NotFoundError,  'NotFoundError instanceof NotFoundError');
assert(nfe.statusCode    === 404,     'NotFoundError.statusCode = 404');
assert(nfe.isOperational === true,    'NotFoundError.isOperational = true');
assert(nfe.resource      === 'User',  'NotFoundError.resource stored');
assert(nfe.name === 'NotFoundError',  'NotFoundError.name correct');
assert(typeof nfe.stack === 'string', 'NotFoundError has stack trace');

// ValidationError
const ve = new ValidationError('Bad input', { email: 'invalid' });
assert(ve instanceof Error,             'ValidationError instanceof Error');
assert(ve instanceof AppError,          'ValidationError instanceof AppError');
assert(ve instanceof ValidationError,   'ValidationError instanceof ValidationError');
assert(ve.statusCode     === 422,       'ValidationError.statusCode = 422');
assert(ve.isOperational  === true,      'ValidationError.isOperational = true');
assert(ve.fields.email   === 'invalid', 'ValidationError.fields stored');
assert(ve.name === 'ValidationError',   'ValidationError.name correct');

// DatabaseError
const cause = new Error('ECONNREFUSED');
const dbe = new DatabaseError('pg timeout', cause);
assert(dbe instanceof Error,           'DatabaseError instanceof Error');
assert(dbe instanceof AppError,        'DatabaseError instanceof AppError');
assert(dbe instanceof DatabaseError,   'DatabaseError instanceof DatabaseError');
assert(dbe.statusCode    === 503,      'DatabaseError.statusCode = 503');
assert(dbe.isOperational === false,    'DatabaseError.isOperational = false');
assert(dbe.cause         === cause,    'DatabaseError.cause stored');
assert(dbe.name === 'DatabaseError',   'DatabaseError.name correct');

// Defaults
assert(new NotFoundError().message   === 'Resource not found',        'NotFoundError default message');
assert(new ValidationError().message === 'Validation failed',         'ValidationError default message');
assert(new DatabaseError().message   === 'A database error occurred', 'DatabaseError default message');
assert(Object.keys(new ValidationError().fields).length === 0,        'ValidationError default fields = {}');
assert(new DatabaseError().cause     === null,                         'DatabaseError default cause = null');

// ---------------------------------------------------------------------------
// 2. Error-handler middleware tests (development mode – stack exposed)
// ---------------------------------------------------------------------------
console.log('\n── errorHandler middleware tests ────────────────────────────');

// NotFoundError
{
  const { status, body } = runErrorHandler(new NotFoundError('User 99 not found', 'User'));
  assert(status        === 404,              'NotFoundError → 404');
  assert(body.error    === 'Not Found',      'NotFoundError → error label');
  assert(body.message  === 'User 99 not found', 'NotFoundError → message exposed (operational)');
  assert(typeof body.stack === 'string',     'NotFoundError → stack in dev mode');
  assert(body.fields   === undefined,        'NotFoundError → no fields key');
}

// ValidationError with fields
{
  const { status, body } = runErrorHandler(
    new ValidationError('Bad input', { email: 'invalid email', name: 'required' })
  );
  assert(status           === 422,              'ValidationError → 422');
  assert(body.error       === 'Validation Error','ValidationError → error label');
  assert(body.message     === 'Bad input',      'ValidationError → message exposed');
  assert(body.fields.email === 'invalid email', 'ValidationError → fields.email');
  assert(body.fields.name  === 'required',      'ValidationError → fields.name');
}

// ValidationError without fields
{
  const { status, body } = runErrorHandler(new ValidationError('Missing body'));
  assert(status        === 422,   'ValidationError (no fields) → 422');
  assert(body.fields   === undefined, 'ValidationError empty fields → not serialised');
}

// DatabaseError (non-operational) – raw message suppressed
{
  const { status, body } = runErrorHandler(
    new DatabaseError('pg timeout', new Error('ECONNREFUSED'))
  );
  assert(status        === 503,                 'DatabaseError → 503');
  assert(body.error    === 'Service Unavailable','DatabaseError → error label');
  assert(
    body.message === 'An unexpected error occurred. Please try again later.',
    'DatabaseError → generic message (non-operational)'
  );
  assert(body.cause    === 'ECONNREFUSED',      'DatabaseError → cause in dev mode');
}

// Plain Error (non-operational) – raw message suppressed
{
  const { status, body } = runErrorHandler(new Error('boom'));
  assert(status        === 500,                  'plain Error → 500');
  assert(body.error    === 'Internal Server Error','plain Error → error label');
  assert(
    body.message === 'An unexpected error occurred. Please try again later.',
    'plain Error → generic message'
  );
}

// ---------------------------------------------------------------------------
// 3. errorHandler hides internal details in production mode
// ---------------------------------------------------------------------------
console.log('\n── production mode tests ────────────────────────────────────');

process.env.NODE_ENV = 'production';

{
  const { body } = runErrorHandler(new DatabaseError('secret internals'));
  assert(body.stack === undefined, 'DatabaseError → no stack in production');
  assert(body.cause === undefined, 'DatabaseError → no cause in production');
}

{
  const { body } = runErrorHandler(new NotFoundError('User 1 missing'));
  assert(body.stack   === undefined,       'NotFoundError → no stack in production');
  assert(body.message === 'User 1 missing','NotFoundError → message still shown (operational)');
}

process.env.NODE_ENV = 'development'; // restore

// ---------------------------------------------------------------------------
// 4. Route-level integration: sync throws reach the error handler
//    (Express 5 auto-wraps sync throws; we test by directly calling the
//     route handler and verifying it throws the right error type)
// ---------------------------------------------------------------------------
console.log('\n── route throw integration tests ────────────────────────────');

// GET /users/:id – non-integer id → ValidationError
{
  let caught = null;
  try {
    const routeHandler = app._router.stack
      .filter(l => l.route && l.route.path === '/users/:id')
      .pop().route.stack[0].handle;
    routeHandler({ params: { id: 'abc' } }, {}, () => {});
  } catch (e) { caught = e; }
  assert(caught instanceof ValidationError, 'GET /users/:id non-integer → throws ValidationError');
  assert(caught.statusCode === 422,         'GET /users/:id non-integer → statusCode 422');
  assert(typeof caught.fields.id === 'string', 'GET /users/:id non-integer → fields.id present');
}

// GET /users/:id – valid id but not in the map → NotFoundError
{
  let caught = null;
  try {
    const routeHandler = app._router.stack
      .filter(l => l.route && l.route.path === '/users/:id')
      .pop().route.stack[0].handle;
    routeHandler({ params: { id: '99' } }, {}, () => {});
  } catch (e) { caught = e; }
  assert(caught instanceof NotFoundError, 'GET /users/:id unknown id → throws NotFoundError');
  assert(caught.statusCode === 404,       'GET /users/:id unknown id → statusCode 404');
  assert(caught.resource   === 'User',    'GET /users/:id unknown id → resource = User');
}

// POST /users – missing fields → ValidationError
{
