  } catch (e) { caught = e; }
  assert(caught instanceof ValidationError,       'POST /users empty body → throws ValidationError');
  assert(typeof caught.fields.name  === 'string', 'POST /users empty body → fields.name');
  assert(typeof caught.fields.email === 'string', 'POST /users empty body → fields.email');
}

// POST /users – valid fields but DB unavailable → DatabaseError
{
  let caught = null;
  try {
    const routeHandler = app._router.stack
      .filter(l => l.route && l.route.path === '/users')
      .filter(l => l.route.methods.post)
      .pop().route.stack[0].handle;
    routeHandler({ body: { name: 'Carol', email: 'carol@example.com' } }, {}, () => {});
  } catch (e) { caught = e; }
  assert(caught instanceof DatabaseError, 'POST /users DB unavailable → throws DatabaseError');
  assert(caught.statusCode === 503,       'POST /users DB unavailable → statusCode 503');
  assert(caught.cause instanceof Error,   'POST /users DB unavailable → cause attached');
