/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the native Error so that:
 *  - instanceof checks work correctly throughout the app.
 *  - Stack traces are captured at the throw site.
 *  - The error-handling middleware has a single, predictable contract:
 *      err.statusCode  – HTTP status to send
 *      err.code        – machine-readable identifier (useful for clients / logs)
 *      err.message     – human-readable description
 *      err.details     – optional structured payload (e.g. field-level validation info)
 *      err.isOperational – true  → expected, "safe" error we handle gracefully
 *                          false → unexpected programmer error (should crash / alert)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable error description.
   * @param {number}  statusCode    - HTTP status code to return.
   * @param {string}  code          - Machine-readable error code, e.g. 'NOT_FOUND'.
   * @param {*}       [details]     - Optional extra data (validation fields, etc.).
   * @param {boolean} [isOperational=true] - Whether this is an expected error.
   */
  constructor(message, statusCode, code, details = null, isOperational = true) {
    super(message);

    // Maintains proper prototype chain for `instanceof` in transpiled ES5 output.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = new.target.name; // 'NotFoundError', 'ValidationError', etc.
    this.statusCode  = statusCode;
    this.code        = code;
    this.details     = details;
    this.isOperational = isOperational;

    // Capture stack trace, excluding the constructor call from it.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }

  /**
   * Serialises the error to a plain object safe for JSON responses.
   * Sensitive internals (stack trace) are intentionally omitted.
   */
  toJSON() {
    const payload = {
      error: {
        code:    this.code,
        message: this.message,
      },
    };
    if (this.details !== null && this.details !== undefined) {
      payload.error.details = this.details;
    }
    return payload;
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource='Resource'] - Name of the resource that was not found.
   * @param {*}      [details]             - Optional extra context.
   *
   * @example
   *   throw new NotFoundError('User');
   *   // → 404  { error: { code: 'NOT_FOUND', message: 'User not found.' } }
   *
   *   throw new NotFoundError('User', { id: 42 });
   *   // → 404  { error: { code: 'NOT_FOUND', message: 'User not found.', details: { id: 42 } } }
   */
  constructor(resource = 'Resource', details = null) {
    super(
      `${resource} not found.`,
      404,
      'NOT_FOUND',
      details,
    );
  }
}

// ---------------------------------------------------------------------------
// 422 Unprocessable Entity – Validation
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}                     [message='Validation failed.'] - Summary message.
   * @param {Array<{field,message}>|null} [details]  - Per-field error array.
   *
   * @example
   *   throw new ValidationError('Invalid input.', [
   *     { field: 'email', message: 'Must be a valid email address.' },
   *     { field: 'age',   message: 'Must be a positive integer.' },
   *   ]);
   */
  constructor(message = 'Validation failed.', details = null) {
    super(
      message,
      422,
      'VALIDATION_ERROR',
      details,
    );
  }
}

// ---------------------------------------------------------------------------
// 503 Service Unavailable – Database / persistence layer
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred.'] - Human-readable description.
   * @param {*}      [details]   - Optional extra context (query, table, etc.).
   * @param {Error}  [cause]     - The original low-level error to preserve.
   *
   * DatabaseErrors are treated as *non-operational* by default because they
   * usually indicate an infrastructure problem that warrants alerting, not a
   * routine client mistake.  Pass isOperational=true to override.
   *
   * @example
   *   try {
   *     await db.query(sql);
   *   } catch (err) {
   *     throw new DatabaseError('Failed to fetch users.', null, err);
   *   }
   */
  constructor(message = 'A database error occurred.', details = null, cause = null) {
    super(
      message,
      503,
      'DATABASE_ERROR',
      details,
      false, // non-operational: unexpected infrastructure failure
    );

    // Node ≥ 16.9 native cause support; also kept as own property for older runtimes.
    if (cause) {
      this.cause = cause;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * routes/health.js
 * Health-check route.
 */

'use strict';

const express = require('express');
const router  = express.Router();

// GET /health
// Returns a simple liveness signal.  No failure paths are expected here, so no
// custom error throwing is required for this particular route.
router.get('/', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

module.exports = router;

/**
 * routes/users.js
 * User resource routes.
 *
 * All error paths use `throw` (or `next(err)` inside async wrappers) so that
 * the centralised error-handling middleware in app.js is the single place
 * responsible for shaping and sending error responses.
 */

'use strict';

const express          = require('express');
const router           = express.Router();
const { NotFoundError, ValidationError, DatabaseError } = require('../errors');

// ---------------------------------------------------------------------------
// In-memory data store (stand-in for a real database layer)
// ---------------------------------------------------------------------------

let users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

let nextId = 3;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler so that any thrown error is forwarded to the
 * Express error-handling middleware via next(err).
 *
 * This lets us write `throw new SomeError(...)` in async handlers without
 * needing try/catch blocks everywhere.
 *
 * @param {Function} fn - Async route handler.
 * @returns {Function}  Standard Express (req, res, next) handler.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Validates the fields required to create or replace a user.
 *
 * @param {object} body - Request body.
 * @throws {ValidationError} When required fields are missing or malformed.
 */
function validateUserBody(body) {
  const fieldErrors = [];

  if (!body.name || typeof body.name !== 'string' || body.name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string.' });
  }

  if (!body.email || typeof body.email !== 'string') {
    fieldErrors.push({ field: 'email', message: 'Email is required and must be a string.' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim())) {
    fieldErrors.push({ field: 'email', message: 'Email must be a valid email address.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('User validation failed.', fieldErrors);
  }
}

/**
 * Simulates fetching all users from a persistence layer.
 *
 * @returns {Promise<Array>}
 * @throws {DatabaseError} When the underlying store is unavailable.
 */
async function fetchAllUsers() {
  try {
    // Replace the body of this function with a real DB call, e.g.:
    //   return await db.query('SELECT * FROM users');
    return users;
  } catch (err) {
    throw new DatabaseError('Failed to retrieve users from the database.', null, err);
  }
}

/**
 * Simulates fetching a single user by id.
 *
 * @param {number} id
 * @returns {Promise<object>}
 * @throws {NotFoundError}  When no user with the given id exists.
 * @throws {DatabaseError}  When the underlying store is unavailable.
 */
async function fetchUserById(id) {
  try {
    const user = users.find((u) => u.id === id);
    if (!user) {
      throw new NotFoundError('User', { id });
    }
    return user;
  } catch (err) {
    // Re-throw our own operational errors unchanged; wrap only unexpected ones.
    if (err.isOperational !== undefined) throw err;
    throw new DatabaseError('Failed to retrieve user from the database.', { id }, err);
  }
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /users — list all users
router.get(
  '/',
  asyncHandler(async (req, res) => {
    const allUsers = await fetchAllUsers();
    res.json(allUsers);
  }),
);

// GET /users/:id — get a single user
router.get(
  '/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid user ID.', [
        { field: 'id', message: 'ID must be a positive integer.' },
      ]);
    }

    const user = await fetchUserById(id);
    res.json(user);
  }),
);

// POST /users — create a new user
router.post(
  '/',
  asyncHandler(async (req, res) => {
    validateUserBody(req.body);

    try {
      const newUser = {
        id:    nextId++,
        name:  req.body.name.trim(),
        email: req.body.email.trim().toLowerCase(),
      };
      users.push(newUser);
      res.status(201).json(newUser);
    } catch (err) {
      if (err.isOperational !== undefined) throw err;
      throw new DatabaseError('Failed to persist the new user.', null, err);
    }
  }),
);

// PUT /users/:id — replace a user
router.put(
  '/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid user ID.', [
        { field: 'id', message: 'ID must be a positive integer.' },
      ]);
    }

    validateUserBody(req.body);

    // Confirm the user exists before attempting an update.
    await fetchUserById(id);

    try {
