/**
 * routes/users.js
 * User resource routes.
 *
 * All error paths use `throw` (or `next(err)` inside async wrappers) so that
 * the centralised error-handling middleware in app.js is the single place
 * responsible for shaping and sending error responses.
 */

'use strict';

const express          = require('express');
const router           = express.Router();
const { NotFoundError, ValidationError, DatabaseError } = require('../errors');

// ---------------------------------------------------------------------------
// In-memory data store (stand-in for a real database layer)
// ---------------------------------------------------------------------------

let users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

let nextId = 3;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler so that any thrown error is forwarded to the
 * Express error-handling middleware via next(err).
 *
 * This lets us write `throw new SomeError(...)` in async handlers without
 * needing try/catch blocks everywhere.
 *
 * @param {Function} fn - Async route handler.
 * @returns {Function}  Standard Express (req, res, next) handler.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Validates the fields required to create or replace a user.
 *
 * @param {object} body - Request body.
 * @throws {ValidationError} When required fields are missing or malformed.
 */
function validateUserBody(body) {
  const fieldErrors = [];

  if (!body.name || typeof body.name !== 'string' || body.name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string.' });
  }

  if (!body.email || typeof body.email !== 'string') {
    fieldErrors.push({ field: 'email', message: 'Email is required and must be a string.' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim())) {
    fieldErrors.push({ field: 'email', message: 'Email must be a valid email address.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('User validation failed.', fieldErrors);
  }
}

