 * Simulates fetching all users from a persistence layer.
 *
 * @returns {Promise<Array>}
 * @throws {DatabaseError} When the underlying store is unavailable.
 */
async function fetchAllUsers() {
  try {
    // Replace the body of this function with a real DB call, e.g.:
    //   return await db.query('SELECT * FROM users');
    return users;
  } catch (err) {
    throw new DatabaseError('Failed to retrieve users from the database.', null, err);
  }
}

/**
 * Simulates fetching a single user by id.
 *
 * @param {number} id
 * @returns {Promise<object>}
 * @throws {NotFoundError}  When no user with the given id exists.
 * @throws {DatabaseError}  When the underlying store is unavailable.
 */
async function fetchUserById(id) {
  try {
    const user = users.find((u) => u.id === id);
    if (!user) {
      throw new NotFoundError('User', { id });
    }
    return user;
  } catch (err) {
    // Re-throw our own operational errors unchanged; wrap only unexpected ones.
    if (err.isOperational !== undefined) throw err;
    throw new DatabaseError('Failed to retrieve user from the database.', { id }, err);
  }
