router.get(
  '/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid user ID.', [
        { field: 'id', message: 'ID must be a positive integer.' },
      ]);
    }

    const user = await fetchUserById(id);
    res.json(user);
  }),
);

// POST /users — create a new user
router.post(
  '/',
  asyncHandler(async (req, res) => {
    validateUserBody(req.body);

    try {
      const newUser = {
        id:    nextId++,
        name:  req.body.name.trim(),
        email: req.body.email.trim().toLowerCase(),
      };
      users.push(newUser);
      res.status(201).json(newUser);
    } catch (err) {
      if (err.isOperational !== undefined) throw err;
      throw new DatabaseError('Failed to persist the new user.', null, err);
    }
  }),
);

// PUT /users/:id — replace a user
router.put(
  '/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid user ID.', [
        { field: 'id', message: 'ID must be a positive integer.' },
      ]);
    }

    validateUserBody(req.body);

    // Confirm the user exists before attempting an update.
    await fetchUserById(id);

    try {
      users = users.map((u) =>
        u.id === id
          ? { id, name: req.body.name.trim(), email: req.body.email.trim().toLowerCase() }
          : u,
      );
      const updated = users.find((u) => u.id === id);
      res.json(updated);
    } catch (err) {
      if (err.isOperational !== undefined) throw err;
      throw new DatabaseError('Failed to update user in the database.', { id }, err);
    }
  }),
);

// DELETE /users/:id — remove a user
router.delete(
  '/:id',
  asyncHandler(async (req, res) => {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid user ID.', [
        { field: 'id', message: 'ID must be a positive integer.' },
      ]);
    }

    // Confirm the user exists; fetchUserById throws NotFoundError if not.
    await fetchUserById(id);

