/**
 * errors.js
 * ---------
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error and adds two extra properties:
 *   • statusCode – the HTTP status that will be sent to the client
 *   • isOperational – true for "expected" errors (invalid input, missing
 *     records, …) so the global handler can distinguish them from
 *     unexpected programmer errors and log accordingly.
 */

'use strict';

// ─── Base Application Error ───────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string} message      - Human-readable description.
   * @param {number} statusCode   - HTTP status code (e.g. 400, 404, 500).
   * @param {string} [errorCode]  - Optional machine-readable code (e.g. 'USER_NOT_FOUND').
   */
  constructor(message, statusCode, errorCode) {
    super(message);

    // Maintain proper prototype chain so `instanceof` checks work correctly
    // after TypeScript / Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.errorCode = errorCode || this.constructor.name.toUpperCase();
    this.isOperational = true; // Expected, handleable error

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── 404 Not Found ────────────────────────────────────────────────────────────

/**
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message]    - Defaults to 'Resource not found'.
   * @param {string} [errorCode]  - Defaults to 'NOT_FOUND'.
   */
  constructor(message = 'Resource not found', errorCode = 'NOT_FOUND') {
    super(message, 404, errorCode);
  }
}

// ─── 400 Validation Error ────────────────────────────────────────────────────

/**
 * Thrown when incoming request data fails validation.
 * Optionally carries a `fields` map so clients know exactly which
 * parameters are invalid.
 *
 * @example
 *   throw new ValidationError('Invalid email address', { email: 'Must be a valid email' });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message]           - Defaults to 'Validation failed'.
   * @param {Object} [fields={}]         - Map of field name → error description.
   * @param {string} [errorCode]         - Defaults to 'VALIDATION_ERROR'.
   */
  constructor(message = 'Validation failed', fields = {}, errorCode = 'VALIDATION_ERROR') {
    super(message, 400, errorCode);
    this.fields = fields; // e.g. { email: 'Required', age: 'Must be a number' }
  }
}

// ─── 503 Database Error ───────────────────────────────────────────────────────

/**
 * Thrown when a database operation fails (query error, connection loss, …).
 * The original low-level error is captured as `this.cause` for server-side
 * logging without leaking internals to the client.
 *
 * @example
 *   throw new DatabaseError('Failed to fetch users', originalPgError);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]    - Defaults to 'A database error occurred'.
   * @param {Error}  [cause]      - The original low-level error for logging.
   * @param {string} [errorCode]  - Defaults to 'DATABASE_ERROR'.
   */
  constructor(
    message = 'A database error occurred',
    cause = null,
    errorCode = 'DATABASE_ERROR',
  ) {
    super(message, 503, errorCode);
    this.cause = cause; // Kept server-side; never sent to the client
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ─── Mock data ────────────────────────────────────────────────────────────────

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe – always succeeds while the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Query params:
 *   ?limit  (number, 1-100)  – cap the number of results returned.
 */
app.get('/users', (req, res) => {
  const { limit } = req.query;

  if (limit !== undefined) {
    const parsed = Number(limit);

    if (!Number.isInteger(parsed) || parsed < 1 || parsed > 100) {
      throw new ValidationError(
        'Invalid query parameter',
        { limit: 'Must be an integer between 1 and 100' },
      );
    }

    return res.json(USERS.slice(0, parsed));
  }

  res.json(USERS);
});

/**
 * GET /users/:id
 * Returns a single user by numeric ID.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id < 1) {
    throw new ValidationError(
      'Invalid route parameter',
      { id: 'Must be a positive integer' },
    );
  }

  const user = USERS.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'USER_NOT_FOUND');
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 *
 * Body: { name: string, email: string }
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'Required and must be a non-empty string';
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.email = 'Required and must be a valid email address';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Request body validation failed', fieldErrors);
  }

  const newUser = { id: USERS.length + 1, name: name.trim(), email: email.trim() };
  USERS.push(newUser);

  res.status(201).json(newUser);
});

// ─── 404 catch-all ───────────────────────────────────────────────────────────
// Must be placed AFTER all valid routes so it only fires for unknown paths.

app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`, 'ROUTE_NOT_FOUND'));
});

// ─── Centralised error-handling middleware ────────────────────────────────────
// Express identifies this as the error handler because it declares four
// parameters (err, req, res, next).  It MUST be the last app.use() call.

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Operational errors (our own AppError subclasses) ──────────────────────
  if (err instanceof AppError) {
    // Log at warn level – these are expected and don't need a stack trace.
    console.warn(`[${err.errorCode}] ${err.message}`);

    const body = {
      error: {
        status:    err.statusCode,
        errorCode: err.errorCode,
        message:   err.message,
      },
    };

    // Include field-level details for validation errors.
    if (err instanceof ValidationError && Object.keys(err.fields).length > 0) {
      body.error.fields = err.fields;
    }

    // Log the original DB cause server-side without leaking it to the client.
    if (err instanceof DatabaseError && err.cause) {
      console.error('[DatabaseError] Underlying cause:', err.cause);
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Unexpected / programmer errors ───────────────────────────────────────
  // Log the full stack so it can be investigated; return a generic 500 so
  // implementation details are never exposed to the client.
  console.error('[UnhandledError]', err);

  return res.status(500).json({
    error: {
      status:    500,
      errorCode: 'INTERNAL_SERVER_ERROR',
      message:   'An unexpected error occurred. Please try again later.',
    },
  });
});

// ─── Server bootstrap ─────────────────────────────────────────────────────────

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

