/**
 * errors.js
 *
 * Centralised custom error classes.
 * Every class extends the built-in Error and carries:
 *   - message   – human-readable description
 *   - statusCode – HTTP status code used by the error-handling middleware
 *   - code       – stable machine-readable identifier (useful for clients / logging)
 *   - isOperational – true  → expected, "safe" error (4xx); the process should keep running
 *                     false → unexpected, programmer error (5xx); may warrant a restart
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string} message       - Human-readable error description.
   * @param {number} statusCode    - HTTP status code.
   * @param {string} code          - Machine-readable error code.
   * @param {boolean} isOperational - Whether this is an expected (operational) error.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintains proper prototype chain in transpiled environments
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that omits this constructor frame
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /** Serialise the error to a plain object safe to send in an API response. */
  toJSON() {
    return {
      error: {
        code:    this.code,
        message: this.message,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource] - Optional resource name (e.g. 'User', 'Order').
   * @param {string|number} [id] - Optional resource identifier.
   *
   * Examples:
   *   throw new NotFoundError();
   *   throw new NotFoundError('User');
   *   throw new NotFoundError('User', 42);
   */
  constructor(resource, id) {
    let message;

    if (resource && id !== undefined) {
      message = `${resource} with id '${id}' was not found.`;
    } else if (resource) {
      message = `${resource} was not found.`;
    } else {
      message = 'The requested resource was not found.';
    }

    super(message, 404, 'NOT_FOUND');

    this.resource = resource || null;
    this.resourceId = id !== undefined ? id : null;
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string} message          - Top-level description of what failed.
   * @param {Object[]} [fields]       - Per-field validation failures.
   *   Each entry: { field: string, message: string }
   *
   * Examples:
   *   throw new ValidationError('Request body is invalid.');
   *   throw new ValidationError('Invalid input.', [
   *     { field: 'email', message: 'Must be a valid email address.' },
   *     { field: 'age',   message: 'Must be a positive integer.' },
   *   ]);
   */
  constructor(message = 'Validation failed.', fields = []) {
    super(message, 422, 'VALIDATION_ERROR');

    // fields: array of { field, message } objects for per-field reporting
    this.fields = Array.isArray(fields) ? fields : [];
  }

  /** Override toJSON to include per-field details when present. */
  toJSON() {
    const base = super.toJSON();

    if (this.fields.length > 0) {
      base.error.fields = this.fields;
    }

    return base;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]   - Description of the database problem.
   * @param {Error}  [cause]     - Original error thrown by the DB driver/ORM.
   *
   * DatabaseError is marked non-operational (isOperational = false) because
   * a database failure is unexpected and may require operator intervention.
   *
   * The original cause is stored but NEVER forwarded to API responses to
   * avoid leaking internal connection strings, query details, etc.
   *
   * Examples:
   *   throw new DatabaseError();
   *   throw new DatabaseError('Could not reach database.');
   *   throw new DatabaseError('Query failed.', originalPgError);
   */
  constructor(message = 'A database error occurred.', cause = null) {
    super(message, 503, 'DATABASE_ERROR', /* isOperational */ false);

    // Store the raw cause for server-side logging only – never exposed in toJSON
    this.cause = cause;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

/**
 * app.js
 *
 * Express application with centralised error handling.
 *
 * Error flow
 * ----------
 * Route handlers throw AppError subclasses (or plain Errors).
 * Nothing in a route ever calls res.status().json() for error cases.
 * All error responses are produced exclusively by the two middleware
 * functions at the bottom:
 *
 *   1. notFoundHandler  – catches requests that matched no route (404)
 *   2. errorHandler     – converts any Error into a structured JSON response
 */

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Request parsing middleware
// ---------------------------------------------------------------------------

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 *
 * Basic liveness check.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns all users.
 * Demonstrates: normal success path.
 */
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  res.json(users);
});

/**
 * GET /users/:id
 *
 * Returns a single user by numeric id.
 * Demonstrates: NotFoundError and ValidationError via throw.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  // Validate: id must be a positive integer
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user id.', [
      { field: 'id', message: 'Must be a positive integer.' },
    ]);
  }

  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];

  if (!user) {
    throw new NotFoundError('User', id);
  }

  res.json(user);
});

/**
 * POST /users
 *
 * Creates a new user.
 * Demonstrates: multi-field ValidationError and DatabaseError via throw.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};

  // Collect all field-level failures before throwing so the client gets
  // everything wrong in a single response.
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string.' });
  }

  if (!email || typeof email !== 'string') {
    fieldErrors.push({ field: 'email', message: 'Email is required.' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'Must be a valid email address.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Request body is invalid.', fieldErrors);
  }

  // Simulate a database write.  In production this would be an async call to
  // your DB layer; if that layer throws, wrap it in a DatabaseError so the
  // central handler produces the right HTTP response.
  let newUser;
  try {
    // --- replace with real DB call ---
    newUser = { id: 3, name: name.trim(), email };
  } catch (dbErr) {
    throw new DatabaseError('Could not save the new user.', dbErr);
  }

  res.status(201).json(newUser);
});

// ---------------------------------------------------------------------------
// 404 catch-all – must be placed AFTER all routes
// ---------------------------------------------------------------------------

/**
 * Any request that reaches this handler matched no route above.
 * We throw (not next()) so the error handler below owns ALL error formatting.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route '${req.method} ${req.path}' does not exist.`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * Express identifies error-handling middleware by its four-argument signature.
 *
 * Responsibilities:
 *  1. Log the error (server-side only).
 *  2. Determine the HTTP status code and response body.
 *  3. Avoid leaking internal details (stack traces, DB messages) to clients.
 *
 * Error taxonomy handled:
 *  - AppError subclasses (NotFoundError, ValidationError, DatabaseError, …)
 *    → use their own statusCode / toJSON()
 *  - Express body-parser SyntaxError (malformed JSON)
 *    → mapped to 400 ValidationError
 *  - Anything else (programmer errors, unexpected throws)
 *    → generic 500 response; full details logged server-side only
 *
 * @param {Error}           err
 * @param {import('express').Request}  req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} _next  - Required by Express even when unused
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, _res, next) => {
  // ── 1. Logging ────────────────────────────────────────────────────────────
  // Always log the full error server-side (stack, cause, etc.).
  // Non-operational errors (e.g. DatabaseError) are logged at ERROR level
  // and could trigger an alert / process restart in production.
  const isOperational = err instanceof AppError && err.isOperational;
  const logLevel      = isOperational ? 'warn' : 'error';

  console[logLevel]({
    // Request context
    method:  req.method,
    path:    req.path,
    // Error details (never forwarded to the client)
    name:    err.name,
    message: err.message,
    code:    err.code,
    stack:   err.stack,
    // Include the original DB/driver cause when present
    ...(err.cause && { cause: err.cause }),
  });

  // ── 2. Normalise error type ───────────────────────────────────────────────

  // Express body-parser sends a SyntaxError for malformed JSON payloads.
  // Map it to a proper ValidationError so the client gets a 422 with a
  // consistent error shape instead of a raw 400/500.
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    err = new ValidationError('Request body contains invalid JSON.');
  }

  // ── 3. Build and send the response ───────────────────────────────────────

  if (err instanceof AppError) {
    return _res.status(err.statusCode).json(err.toJSON());
  }

  // Unknown / unexpected error – return a generic 500 and hide internals.
  return _res.status(500).json({
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ---------------------------------------------------------------------------
// Start server (skip when required by tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

