const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let passed = 0;
let failed = 0;

function assert(label, condition) {
  if (condition) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}`);
    failed++;
  }
}

// ── AppError (base) ────────────────────────────────────────────────────────
console.log('\nAppError');
const base = new AppError('something broke', 500, 'GENERIC', false);
assert('instanceof Error',    base instanceof Error);
assert('instanceof AppError', base instanceof AppError);
assert('statusCode 500',      base.statusCode === 500);
assert('code GENERIC',        base.code === 'GENERIC');
assert('isOperational false', base.isOperational === false);
assert('name is AppError',    base.name === 'AppError');
assert('toJSON shape', (() => {
  const j = base.toJSON();
  return j.error && j.error.code === 'GENERIC' && j.error.message === 'something broke';
})());

// ── NotFoundError ──────────────────────────────────────────────────────────
console.log('\nNotFoundError');
const nfe1 = new NotFoundError();
const nfe2 = new NotFoundError('User');
const nfe3 = new NotFoundError('User', 42);

assert('instanceof AppError',     nfe1 instanceof AppError);
assert('instanceof NotFoundError',nfe1 instanceof NotFoundError);
assert('statusCode 404',          nfe1.statusCode === 404);
assert('code NOT_FOUND',          nfe1.code === 'NOT_FOUND');
assert('isOperational true',      nfe1.isOperational === true);
assert('generic message',         nfe1.message === 'The requested resource was not found.');
assert('resource-only message',   nfe2.message === 'User was not found.');
assert('resource+id message',     nfe3.message === "User with id '42' was not found.");
assert('resource stored',         nfe3.resource === 'User');
assert('resourceId stored',       nfe3.resourceId === 42);
assert('toJSON code NOT_FOUND',   nfe3.toJSON().error.code === 'NOT_FOUND');

// ── ValidationError ────────────────────────────────────────────────────────
console.log('\nValidationError');
const ve1 = new ValidationError();
const ve2 = new ValidationError('Bad input.', [
  { field: 'email', message: 'Invalid email.' },
  { field: 'age',   message: 'Must be positive.' },
]);

assert('instanceof AppError',       ve1 instanceof AppError);
assert('instanceof ValidationError',ve1 instanceof ValidationError);
assert('statusCode 422',            ve1.statusCode === 422);
assert('code VALIDATION_ERROR',     ve1.code === 'VALIDATION_ERROR');
assert('isOperational true',        ve1.isOperational === true);
assert('default message',           ve1.message === 'Validation failed.');
assert('no fields in toJSON (empty)',!ve1.toJSON().error.fields);
assert('fields in toJSON (non-empty)',(() => {
  const j = ve2.toJSON();
  return Array.isArray(j.error.fields) && j.error.fields.length === 2;
})());
assert('field entries correct', (() => {
  const [f1, f2] = ve2.toJSON().error.fields;
  return f1.field === 'email' && f2.field === 'age';
})());

// ── DatabaseError ──────────────────────────────────────────────────────────
console.log('\nDatabaseError');
const rawErr = new Error('Connection refused');
const dbe    = new DatabaseError('Query failed.', rawErr);

assert('instanceof AppError',    dbe instanceof AppError);
assert('instanceof DatabaseError',dbe instanceof DatabaseError);
assert('statusCode 503',         dbe.statusCode === 503);
assert('code DATABASE_ERROR',    dbe.code === 'DATABASE_ERROR');
assert('isOperational false',    dbe.isOperational === false);
assert('cause stored',           dbe.cause === rawErr);
assert('cause NOT in toJSON', (() => {
  const j = dbe.toJSON();
  return !j.error.cause && !j.cause;
})());

// ── Summary ────────────────────────────────────────────────────────────────
console.log(`\n${passed + failed} tests: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
EOF

