/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error and adds two extra fields:
 *   - statusCode  – the HTTP status code that should be sent to the client
 *   - code        – a stable, machine-readable string useful for client logic
 *
 * Usage (inside a route or middleware):
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('email is required');
 *   throw new DatabaseError('Query timed out');
 *
 * The central error-handling middleware in app.js will catch every thrown
 * error and convert it into a consistent JSON response automatically.
 */

'use strict';

// ─── Base application error ───────────────────────────────────────────────────

/**
 * AppError is the shared base class for all custom errors.
 * It is not intended to be thrown directly; use one of the subclasses below.
 *
 * @param {string}  message     - Human-readable description of the error.
 * @param {number}  statusCode  - HTTP status code (e.g. 400, 404, 500).
 * @param {string}  code        - Machine-readable error identifier.
 * @param {boolean} isOperational
 *   true  → the error is a known, expected failure (bad input, missing record, …).
 *            The central handler will expose its message to the client.
 *   false → the error is an unexpected programmer mistake or system failure.
 *            The central handler will hide the raw message in production.
 */
class AppError extends Error {
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore the correct class name so stack traces read correctly.
    this.name = this.constructor.name;

    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not inside
    // the AppError constructor itself.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── Concrete error classes ───────────────────────────────────────────────────

/**
 * NotFoundError — 404
 * Thrown when a requested resource cannot be located.
 *
 * @example
 *   throw new NotFoundError('User with id 42 not found');
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   */
  constructor(message = 'Resource not found') {
    super(message, 404, 'NOT_FOUND');
  }
}

/**
 * ValidationError — 400
 * Thrown when user-supplied input fails a validation rule.
 *
 * The optional `fields` map lets callers attach per-field error details,
 * which the central handler will include in the response body so that
 * API consumers can surface precise feedback (e.g. form validation).
 *
 * @example
 *   throw new ValidationError('Invalid request body');
 *   throw new ValidationError('Validation failed', { email: 'must be a valid email' });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message='Validation failed']
   * @param {Record<string, string>} [fields={}]
   *   Optional map of { fieldName: errorMessage } pairs.
   */
  constructor(message = 'Validation failed', fields = {}) {
    super(message, 400, 'VALIDATION_ERROR');
    this.fields = fields; // surfaced in the JSON response when present
  }
}

/**
 * DatabaseError — 503
 * Thrown when a persistence operation fails (query error, connection loss, …).
 *
 * `isOperational` is set to false because database failures are unexpected;
 * the central handler will avoid leaking raw DB messages to clients in
 * production while still logging the full detail server-side.
 *
 * @example
 *   throw new DatabaseError('Connection pool exhausted');
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   */
  constructor(message = 'A database error occurred') {
    // isOperational = false: treat as a critical/unexpected failure.
    super(message, 503, 'DATABASE_ERROR', false);
  }
