  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Example: surface a DatabaseError when the store signals unavailability.
  if (!users) {
    throw new DatabaseError('User store is unavailable');
  }

  res.json(users);
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Error paths:
 *   • 400 ValidationError  – id is not a positive integer
 *   • 404 NotFoundError    – no user exists with that id
 */
