  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User id must be a positive integer', {
      id: 'must be a positive integer',
    });
  }

  // Simulated user store — replace with a real DB call in production.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`);
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 *
 * Error paths:
 *   • 400 ValidationError – required fields are missing or malformed
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'name is required and must be a non-empty string';
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    fieldErrors.email = 'email is required and must be a valid email address';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Invalid user payload', fieldErrors);
  }

  // Simulated creation — replace with a real DB insert in production.
  const newUser = { id: Date.now(), name: name.trim(), email: email.trim() };
  res.status(201).json(newUser);
});

// ─── 404 catch-all (must come after all real routes) ─────────────────────────

/**
 * Any request that reaches this point did not match a defined route.
 * We throw a NotFoundError so it flows through the same central handler.
 */
app.use((req, _res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path} not found`));
});

// ─── Centralised error-handling middleware ────────────────────────────────────

/**
 * errorHandler
 *
 * Express recognises a four-argument middleware function as an error handler.
 * It is intentionally placed last so that every error thrown or passed via
 * next(err) anywhere in the application lands here.
 *
 * Response shape
 * ──────────────
 * {
 *   "error": {
 *     "code":    "NOT_FOUND",           // machine-readable, always present
 *     "message": "User … not found",    // omitted for non-operational errors
 *                                        // in production
 *     "fields":  { … }                  // only present on ValidationError
 *   }
 * }
 *
 * Logging
 * ───────
 * Operational errors are logged at warn level (they are expected failure
 * modes).  Non-operational errors are logged at error level and include the
 * full stack trace so engineers can investigate.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isProduction = process.env.NODE_ENV === 'production';

  // ── Determine HTTP status code ─────────────────────────────────────────────
  // Use the status attached to custom AppError subclasses; fall back to 500
  // for any unrecognised / native Error that slips through.
  const statusCode = err.statusCode ?? 500;

  // ── Logging ────────────────────────────────────────────────────────────────
  if (err.isOperational) {
    // Known, expected failure — log at warn to reduce noise.
    console.warn(`[${err.code ?? 'ERROR'}] ${err.message}`);
  } else {
    // Unexpected failure — log the full stack so it can be investigated.
    console.error('[UNEXPECTED ERROR]', err);
  }

  // ── Build the response body ────────────────────────────────────────────────
  const body = { error: {} };

  // code — always present so clients can branch on a stable identifier.
  body.error.code = err.code ?? 'INTERNAL_SERVER_ERROR';

  // message — hide internal detail for non-operational errors in production.
  if (err.isOperational || !isProduction) {
    body.error.message = err.message;
  } else {
    body.error.message = 'An unexpected error occurred. Please try again later.';
  }

  // fields — only attached when the error carries per-field validation detail.
  if (err.fields && Object.keys(err.fields).length > 0) {
    body.error.fields = err.fields;
  }

  // stack — only included outside production to assist local debugging.
  if (!isProduction && err.stack) {
    body.error.stack = err.stack;
  }

  res.status(statusCode).json(body);
});

// ─── Server bootstrap ─────────────────────────────────────────────────────────

const PORT = process.env.PORT ?? 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

