  const body = { error: {} };

  // code — always present so clients can branch on a stable identifier.
  body.error.code = err.code ?? 'INTERNAL_SERVER_ERROR';

  // message — hide internal detail for non-operational errors in production.
  if (err.isOperational || !isProduction) {
    body.error.message = err.message;
  } else {
    body.error.message = 'An unexpected error occurred. Please try again later.';
  }

  // fields — only attached when the error carries per-field validation detail.
  if (err.fields && Object.keys(err.fields).length > 0) {
    body.error.fields = err.fields;
  }

  // stack — only included outside production to assist local debugging.
  if (!isProduction && err.stack) {
    body.error.stack = err.stack;
  }

  res.status(statusCode).json(body);
});

// ─── Server bootstrap ─────────────────────────────────────────────────────────

const PORT = process.env.PORT ?? 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

