// 404 catch-all — must be placed AFTER all real routes
// ---------------------------------------------------------------------------

/**
 * Any request that falls through all routes above has no matching handler.
 * We throw (rather than call next()) for consistency — the error handler below
 * will catch it identically either way.
 */
app.use((req, _res) => {
  throw new NotFoundError(`Route '${req.method} ${req.path}' not found`);
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Express identifies this as an error-handling middleware because it declares
 * exactly four parameters (err, req, res, next).  It must be registered LAST.
 *
 * Responsibilities:
 *   1. Normalise any thrown value into a consistent shape.
 *   2. Log at the appropriate level.
 *   3. Send a single, structured JSON response — nowhere else in the app does this.
 *
 * Security note: raw Error messages and stack traces are NEVER forwarded to the
 * client in production to avoid leaking implementation details.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV !== 'production';

  // ── 1. Determine whether this is a known operational error ──────────────────
  if (err instanceof AppError) {

    // Operational errors (bad input, missing rows) → warn-level log
    if (err.isOperational) {
      console.warn(`[WARN] ${err.code} — ${err.message}`);
    } else {
      // Non-operational errors (e.g. DatabaseError) → error-level log with cause
      console.error(`[ERROR] ${err.code} — ${err.message}`, {
        cause:  err.cause  ?? null,
        stack:  err.stack,
      });
    }

    // Delegate JSON serialisation to the error's own toJSON() so sub-classes
    // (e.g. ValidationError) can include extra fields like `details`.
    return res.status(err.statusCode).json(err.toJSON());
  }

  // ── 2. Unexpected / programmer errors ───────────────────────────────────────
  console.error('[ERROR] Unhandled error', {
    message: err.message,
    stack:   err.stack,
  });

  // Never expose internal error details in production.
  const message = isDev ? err.message : 'An unexpected error occurred';

  return res.status(500).json({
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message,
      // Include the stack in dev responses to aid debugging.
      ...(isDev && { stack: err.stack }),
    },
  });
});

