// ─── Minimal Express mock ────────────────────────────────────────────────────
// Replicate just enough of Express's routing + error-handler contract so we
// can test app.js end-to-end without installing the package.

function createMockExpress() {
  const routes   = [];  // { method, path, handler }
  const mwStack  = [];  // generic middleware (no method)

  function matchRoute(method, path) {
    // Supports :param segments
    for (const r of routes) {
      if (r.method !== method) continue;
      const re = new RegExp('^' + r.path.replace(/:([^/]+)/g, '([^/]+)') + '$');
      const m  = path.match(re);
      if (m) {
        const paramNames = [...r.path.matchAll(/:([^/]+)/g)].map(x => x[1]);
        const params     = Object.fromEntries(paramNames.map((n, i) => [n, m[i + 1]]));
        return { handler: r.handler, params };
      }
    }
    return null;
  }

  const app = {
    _errorHandlers: [],

    use(fnOrPath, fn) {
      const handler = fn || fnOrPath;
      if (handler.length === 4) {          // (err, req, res, next)
        app._errorHandlers.push(handler);
      } else {
        mwStack.push(handler);
      }
    },

    get(path, handler)  { routes.push({ method: 'GET',  path, handler }); },
    post(path, handler) { routes.push({ method: 'POST', path, handler }); },

    json() { return { _isMock: true }; }, // stub for express.json()

    listen(port, cb) { if (cb) cb(); },
  };

  // ── request helper ──────────────────────────────────────────────────────────
  app.request = function(method, path, body) {
    return new Promise(resolve => {
      const req = {
        method,
        path,
        params: {},
        body: body ?? {},
      };

      const response = {};
      let   statusCode = 200;

      const res = {
        status(code) { statusCode = code; return res; },
        json(data)   {
          response.status = statusCode;
          response.body   = data;
          resolve(response);
        },
      };

      const next = (err) => {
        if (err) {
          // Run error handlers
          const errH = app._errorHandlers[0];
          if (errH) {
            errH(err, req, res, () => {});
          } else {
            resolve({ status: 500, body: { error: 'unhandled' } });
          }
        }
      };

      // Run generic middleware (body parser stub → no-op)
      // Then route
      const match = matchRoute(method, path);

      if (match) {
        req.params = match.params;
        try {
          match.handler(req, res, next);
        } catch (err) {
          next(err);
        }
      } else {
        // Fall through to catch-all 404 middleware
        const catchAll = mwStack.find(m => m.length !== 4);
        if (catchAll) {
          try {
            catchAll(req, res, next);
          } catch (err) {
            next(err);
          }
        } else {
          resolve({ status: 404, body: { error: 'no route' } });
        }
      }
    });
  };

  return app;
}

