/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error and carries:
 *   - message   – human-readable description
 *   - statusCode – HTTP status code used by the error-handling middleware
 *   - code       – machine-readable string for clients / logs
 *   - details    – optional structured payload (validation field list, etc.)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message     - Human-readable error message.
   * @param {number}  statusCode  - HTTP status code to send to the client.
   * @param {string}  code        - Machine-readable error code string.
   * @param {*}       [details]   - Optional extra context (fields, ids, …).
   */
  constructor(message, statusCode, code, details = null) {
    super(message);

    // Restore the correct constructor name in stack traces.
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code;
    this.details = details;

    // Mark errors that originate from our own code so the global handler
    // can distinguish them from unexpected third-party / runtime errors.
    this.isOperational = true;

    // Capture a clean stack trace (V8 only; no-op on other engines).
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Serialise the error into a plain object suitable for JSON responses.
   * The stack trace is never included; callers can add it for dev logging.
   *
   * @returns {{ error: { code: string, message: string, details: * } }}
   */
  toJSON() {
    return {
      error: {
        code: this.code,
        message: this.message,
        ...(this.details !== null && { details: this.details }),
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – resource not found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string}  [message]  - Override the default "Not found" message.
   * @param {*}       [details]  - Optional context (e.g. { id: 42 }).
   *
   * @example
   *   throw new NotFoundError('User not found', { id: req.params.id });
   */
  constructor(message = 'The requested resource was not found.', details = null) {
    super(message, 404, 'NOT_FOUND', details);
  }
}

// ---------------------------------------------------------------------------
// 422 – validation / bad input
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}                   [message]  - Override the default message.
   * @param {Array<{field, message}>}  [details]  - Per-field validation failures.
   *
   * @example
   *   throw new ValidationError('Invalid request body', [
   *     { field: 'email', message: 'Must be a valid e-mail address.' },
   *   ]);
   */
  constructor(
    message = 'The request contained invalid or missing data.',
    details = null,
  ) {
    super(message, 422, 'VALIDATION_ERROR', details);
  }
}

// ---------------------------------------------------------------------------
// 503 – database / persistence layer failure
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string}  [message]  - Override the default message.
   * @param {*}       [details]  - Optional context (query name, table, …).
   *
   * @example
   *   throw new DatabaseError('Failed to fetch user record', { table: 'users' });
   */
  constructor(
    message = 'A database error occurred. Please try again later.',
    details = null,
  ) {
    super(message, 503, 'DATABASE_ERROR', details);
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

/**
 * app.js
 * Express application with centralised error-handling middleware.
 *
 * Error flow
 * ──────────
 *  Route/middleware throws (or calls next(err))
 *      └─▶ asyncHandler catches it and forwards it via next(err)
 *              └─▶ errorHandler middleware formats and sends the response
 */

'use strict';

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

app.use(express.json());

// ===========================================================================
// Utility: async route wrapper
// ===========================================================================

/**
 * Wraps an async route handler so that any rejected promise (or thrown error)
 * is forwarded to Express's next(err) automatically.
 * Without this wrapper Express ≤4 silently swallows async rejections.
 *
 * @param {Function} fn - Async route handler (req, res, next) => Promise
 * @returns {Function}  Standard Express middleware signature.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ===========================================================================
// Routes
// ===========================================================================

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------
app.get('/health', asyncHandler(async (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
}));

// ---------------------------------------------------------------------------
// GET /users  –  return all users
// ---------------------------------------------------------------------------

/** Simulated in-memory user store. */
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

app.get('/users', asyncHandler(async (req, res) => {
  // Example: simulate a database outage when ?failDb=1 is passed.
  if (req.query.failDb === '1') {
    throw new DatabaseError('Failed to retrieve users from the database.', {
      table: 'users',
    });
  }

  res.json(users);
}));

// ---------------------------------------------------------------------------
// GET /users/:id  –  return a single user by numeric id
// ---------------------------------------------------------------------------
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User ID must be a positive integer.', [
      { field: 'id', message: 'Must be a positive integer.' },
    ]);
  }

  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`No user found with ID ${id}.`, { id });
  }

  res.json(user);
}));

// ---------------------------------------------------------------------------
// POST /users  –  create a new user
// ---------------------------------------------------------------------------
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body ?? {};
  const validationIssues = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    validationIssues.push({ field: 'name', message: 'name is required and must be a non-empty string.' });
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    validationIssues.push({ field: 'email', message: 'email is required and must be a valid e-mail address.' });
  }

  if (validationIssues.length > 0) {
    throw new ValidationError('Invalid request body.', validationIssues);
  }

  // Example: simulate a database outage when ?failDb=1 is passed.
  if (req.query.failDb === '1') {
    throw new DatabaseError('Failed to persist the new user.', { table: 'users' });
  }

  const newUser = { id: users.length + 1, name: name.trim(), email: email.trim() };
  users.push(newUser);

  res.status(201).json(newUser);
}));

// ===========================================================================
// 404 catch-all  –  no route matched
// ===========================================================================

/**
 * Must be registered AFTER all valid routes so it only fires when nothing
 * above has handled the request.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ===========================================================================
// Centralised error-handling middleware
// ===========================================================================

/**
 * Express identifies error-handling middleware by its 4-argument signature
 * (err, req, res, next).  It must be the LAST middleware registered.
 *
 * Behaviour
 * ─────────
 *  • Operational errors (AppError subclasses) → structured JSON response with
 *    the error's own statusCode.
 *  • Unexpected/programmer errors              → 500 with a generic message so
 *    internal details are never leaked to clients.
 *  • Stack traces are logged server-side in all cases.
 *
 * @param {Error}             err
 * @param {express.Request}   req
 * @param {express.Response}  res
 * @param {express.NextFunction} next  - Must be declared even if unused so
 *                                       Express recognises the 4-arg signature.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Always log the full error server-side for observability.
  console.error(`[${new Date().toISOString()}] ${req.method} ${req.path} →`, err);

  // Operational error: one of our own AppError subclasses.
  if (err instanceof AppError && err.isOperational) {
    return res.status(err.statusCode).json(err.toJSON());
  }

  // Unexpected/programmer error: hide internals, return a generic 500.
  res.status(500).json({
    error: {
      code: 'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  });
});

// ===========================================================================
// Server bootstrap  (skipped when the module is imported for testing)
// ===========================================================================

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

