# Verify error class hierarchy and serialisation shapes
node -e "
'use strict';
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// ── Inheritance ──────────────────────────────────────────────────────────────
console.assert(new NotFoundError()   instanceof AppError, 'NotFoundError extends AppError');
console.assert(new ValidationError() instanceof AppError, 'ValidationError extends AppError');
console.assert(new DatabaseError()   instanceof AppError, 'DatabaseError extends AppError');
console.assert(new NotFoundError()   instanceof Error,    'NotFoundError extends Error');
console.log('✓ All classes inherit correctly');

// ── Status codes ─────────────────────────────────────────────────────────────
console.assert(new NotFoundError().statusCode   === 404, 'NotFoundError → 404');
console.assert(new ValidationError().statusCode === 422, 'ValidationError → 422');
console.assert(new DatabaseError().statusCode   === 503, 'DatabaseError → 503');
console.log('✓ Status codes correct');

// ── Error codes ──────────────────────────────────────────────────────────────
console.assert(new NotFoundError().code   === 'NOT_FOUND',       'NotFoundError.code');
console.assert(new ValidationError().code === 'VALIDATION_ERROR','ValidationError.code');
console.assert(new DatabaseError().code   === 'DATABASE_ERROR',  'DatabaseError.code');
console.log('✓ Error codes correct');

// ── isOperational flag ───────────────────────────────────────────────────────
console.assert(new NotFoundError().isOperational   === true, 'NotFoundError.isOperational');
console.assert(new ValidationError().isOperational === true, 'ValidationError.isOperational');
console.assert(new DatabaseError().isOperational   === true, 'DatabaseError.isOperational');
console.log('✓ isOperational flag set');

// ── .name reflects class name ────────────────────────────────────────────────
console.assert(new NotFoundError().name   === 'NotFoundError',   '.name NotFoundError');
console.assert(new ValidationError().name === 'ValidationError', '.name ValidationError');
console.assert(new DatabaseError().name   === 'DatabaseError',   '.name DatabaseError');
console.log('✓ .name reflects constructor');

// ── toJSON shape (no details) ────────────────────────────────────────────────
const nfJSON = new NotFoundError('User not found').toJSON();
console.assert(nfJSON.error.code    === 'NOT_FOUND',     'toJSON code');
console.assert(nfJSON.error.message === 'User not found','toJSON message');
console.assert(!('details' in nfJSON.error),             'toJSON omits null details');
console.log('✓ toJSON shape correct (no details)');

// ── toJSON shape (with details) ──────────────────────────────────────────────
const veJSON = new ValidationError('Bad input', [{ field: 'email', message: 'invalid' }]).toJSON();
console.assert(Array.isArray(veJSON.error.details),           'toJSON includes details array');
console.assert(veJSON.error.details[0].field === 'email',     'toJSON details field');
console.log('✓ toJSON shape correct (with details)');

// ── Custom messages override defaults ────────────────────────────────────────
console.assert(new NotFoundError('Custom msg').message   === 'Custom msg', 'custom message NotFoundError');
console.assert(new ValidationError('Custom msg').message === 'Custom msg', 'custom message ValidationError');
console.assert(new DatabaseError('Custom msg').message   === 'Custom msg', 'custom message DatabaseError');
console.log('✓ Custom messages work');

// ── Default messages present ─────────────────────────────────────────────────
console.assert(typeof new NotFoundError().message   === 'string' && new NotFoundError().message.length   > 0, 'default msg NotFoundError');
console.assert(typeof new ValidationError().message === 'string' && new ValidationError().message.length > 0, 'default msg ValidationError');
console.assert(typeof new DatabaseError().message   === 'string' && new DatabaseError().message.length   > 0, 'default msg DatabaseError');
console.log('✓ Default messages present');

console.log('\nAll error class assertions passed.');
"

