'use strict';

// ─── Minimal Express mock ─────────────────────────────────────────────────
const mockExpress = () => {
  const middlewares = [];
  const routes      = {};  // { 'GET /path': handler }

  const app = {
    use(pathOrFn, fn) {
      if (typeof pathOrFn === 'function') middlewares.push({ path: null, fn: pathOrFn, method: '*' });
      else if (typeof fn === 'function')  middlewares.push({ path: pathOrFn, fn, method: '*' });
    },
    get(path, fn)  { routes['GET '  + path] = fn; },
    post(path, fn) { routes['POST ' + path] = fn; },

    // Resolve a literal path against route keys (ignores :param matching for
    // the few parameterised routes we test; we call those handlers directly).
    _handle(method, path, body, query) {
      const key = method + ' ' + path;
      const errors = [];
      let handled = false;

      // Build a minimal req/res pair.
      const req = {
        method,
        path,
        body:  body  ?? {},
        query: query ?? {},
        params: {},
      };
      const captured = { status: 200, body: null };
      const res = {
        status(code) { captured.status = code; return res; },
        json(data)   { captured.body   = data; return res; },
      };

      const next = (err) => { if (err) errors.push(err); };

      // Built-in body-parser middleware (already applied for our tests via req.body).
      // Run matching route handler.
      if (routes[key]) {
        routes[key](req, res, next);
        handled = true;
      }

      // Run error-handler middleware if an error was thrown.
      if (errors.length) {
        const errHandlers = middlewares.filter(m => m.fn.length === 4);
        if (errHandlers.length) errHandlers[0].fn(errors[0], req, res, () => {});
        handled = true;
      }

      return { status: captured.status, body: captured.body };
    },
    listen(port, cb) { if (cb) cb(); return { address: () => ({ port }) }; },
  };
  return app;
};

// Patch require so './errors' resolves normally and 'express' returns the mock.
const Module = require('module');
const _origLoad = Module._load.bind(Module);
Module._load = function(request, parent, isMain) {
  if (request === 'express') return mockExpress;
  return _origLoad(request, parent, isMain);
};

