/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error and carries:
 *   - message   – human-readable description
 *   - statusCode – HTTP status code used by the error-handling middleware
 *   - code       – machine-readable string for clients / logs
 *   - details    – optional structured payload (validation field list, etc.)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message     - Human-readable error message.
   * @param {number}  statusCode  - HTTP status code to send to the client.
   * @param {string}  code        - Machine-readable error code string.
   * @param {*}       [details]   - Optional extra context (fields, ids, …).
   */
  constructor(message, statusCode, code, details = null) {
    super(message);

    // Restore the correct constructor name in stack traces.
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code;
    this.details = details;

    // Mark errors that originate from our own code so the global handler
    // can distinguish them from unexpected third-party / runtime errors.
    this.isOperational = true;

