/**
 * errors.js
 * Centralised custom error classes for the Express application.
 *
 * Every class extends the built-in Error and carries:
 *   - statusCode  – the HTTP status code sent to the client
 *   - code        – a machine-readable string identifier
 *   - isOperational – true for "expected" errors that should be
 *                     surfaced to the client; false for programmer
 *                     mistakes that should not leak internal detail.
 */

'use strict';

// ─── Base application error ────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string}  message       Human-readable description.
   * @param {number}  statusCode    HTTP status code (default 500).
   * @param {string}  code          Machine-readable code (default 'INTERNAL_ERROR').
   * @param {boolean} isOperational Whether this is a known, safe-to-expose error.
   */
  constructor(
    message,
    statusCode = 500,
    code = 'INTERNAL_ERROR',
    isOperational = true,
  ) {
    super(message);

    // Restore the prototype chain (required when extending built-ins in TS/Babel
    // transpiled code; harmless in plain Node.js but a good habit).
    Object.setPrototypeOf(this, new.target.prototype);

    this.name = new.target.name; // e.g. "NotFoundError"
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }
}

// ─── Concrete error classes ────────────────────────────────────────────────

/**
 * 404 Not Found
 * Use when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found');
 *   throw new NotFoundError(`Product ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message]  Defaults to 'Resource not found'.
   * @param {string} [resource] Optional resource name included in the response.
   */
  constructor(message = 'Resource not found', resource = null) {
    super(message, 404, 'NOT_FOUND');
    if (resource) this.resource = resource;
  }
}

/**
 * 422 Unprocessable Entity (Validation)
 * Use when the request is syntactically correct but semantically invalid.
 *
 * @example
 *   throw new ValidationError('Email is required');
 *   throw new ValidationError('Invalid input', [{ field: 'email', msg: '...' }]);
 */
class ValidationError extends AppError {
  /**
   * @param {string}   [message] Defaults to 'Validation failed'.
   * @param {Array}    [errors]  Optional array of field-level error objects.
   */
  constructor(message = 'Validation failed', errors = []) {
    super(message, 422, 'VALIDATION_ERROR');
    this.errors = errors; // e.g. [{ field: 'email', message: 'Invalid format' }]
  }
}

/**
 * 503 Service Unavailable (Database)
 * Use when a database operation fails (connection error, query failure, etc.).
 * Marked as non-operational by default so that internal DB detail is never
 * sent to the client; the error handler will log it and return a generic message.
 *
 * @example
 *   throw new DatabaseError('Connection timeout', originalError);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]       Defaults to 'Database operation failed'.
   * @param {Error}  [originalError] The underlying DB error (logged, never sent to client).
   */
  constructor(message = 'Database operation failed', originalError = null) {
    // isOperational = false → the error handler will NOT expose the message
    super(message, 503, 'DATABASE_ERROR', false);
    if (originalError) this.originalError = originalError;
  }
}

// ─── Exports ───────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

const express = require('express');
const { NotFoundError, ValidationError, DatabaseError, AppError } = require('./errors');

const app = express();

app.use(express.json());

// ─────────────────────────────────────────────────────────────────────────────
// Routes
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe — always succeeds while the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Return all users.
 * Throws DatabaseError if the data layer is unavailable.
 */
app.get('/users', (req, res) => {
  // Simulate a data-access call.
  // In a real app this would be: const users = await UserRepository.findAll();
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  if (!users) {
    // Example: bubble up a database failure instead of inlining res.status(503)
    throw new DatabaseError('Failed to fetch users from the database');
  }

  res.json(users);
});

/**
 * GET /users/:id
 * Return a single user by numeric id.
 * Throws ValidationError for a non-numeric id, NotFoundError when missing.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('User ID must be a positive integer', [
      { field: 'id', message: 'Must be a positive integer' },
    ]);
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'User');
  }

  res.json(user);
});

/**
 * POST /users
 * Create a new user.
 * Throws ValidationError when required fields are absent or malformed.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'A valid email address is required' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Invalid user payload', fieldErrors);
  }

  // Simulate persistence — in a real app: await UserRepository.create({ name, email })
  const newUser = { id: Date.now(), name: name.trim(), email };
  res.status(201).json(newUser);
});

// ─────────────────────────────────────────────────────────────────────────────
// 404 catch-all — must come AFTER all valid routes
// ─────────────────────────────────────────────────────────────────────────────

app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// ─────────────────────────────────────────────────────────────────────────────
// Centralised error-handling middleware
//
// Express identifies this as the error handler because it declares four
// parameters: (err, req, res, next).  It must be registered LAST.
// ─────────────────────────────────────────────────────────────────────────────

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Always log the full error server-side ───────────────────────────────
  const isProduction = process.env.NODE_ENV === 'production';

  if (!isProduction || !err.isOperational) {
    // In development (or for unexpected errors) log the full stack.
    console.error('[error]', err);
  } else {
    // In production, log a one-liner for operational errors.
    console.error(`[error] ${err.name} (${err.statusCode}): ${err.message}`);
  }

  // ── 2. Non-operational errors (DatabaseError, unhandled throws, etc.) ──────
  //    Never leak internal details to the client.
  if (!err.isOperational) {
    return res.status(err.statusCode ?? 500).json({
      status:  'error',
      code:    'INTERNAL_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    });
  }

  // ── 3. Operational errors — safe to surface to the client ─────────────────
  const body = {
    status:  'error',
    code:    err.code,
    message: err.message,
  };

  // Attach field-level details for validation failures.
  if (err instanceof ValidationError && err.errors?.length > 0) {
    body.errors = err.errors;
  }

  // Attach the resource type for not-found failures (optional, helps clients).
  if (err instanceof NotFoundError && err.resource) {
    body.resource = err.resource;
  }

  return res.status(err.statusCode).json(body);
});

// ─────────────────────────────────────────────────────────────────────────────
// Server bootstrap
// ─────────────────────────────────────────────────────────────────────────────

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

