/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Each class extends the built-in Error and carries:
 *  - statusCode  – the HTTP status code to send to the client
 *  - isOperational – true for expected/known errors (network, validation, etc.)
 *                    false (or absent) for unexpected programmer errors
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description.
   * @param {number}  statusCode    - HTTP status code.
   * @param {string}  [errorCode]   - Optional machine-readable code (e.g. "USER_NOT_FOUND").
   * @param {boolean} [isOperational=true] - Whether this is a known operational error.
   */
  constructor(message, statusCode, errorCode, isOperational = true) {
    super(message);

    // Maintain proper prototype chain for instanceof checks
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = new.target.name;
    this.statusCode  = statusCode;
    this.errorCode   = errorCode || 'INTERNAL_ERROR';
    this.isOperational = isOperational;

    // Capture V8 stack trace, excluding the constructor call itself
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 Not Found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * Raised when a requested resource cannot be located.
   *
   * @param {string} [resource='Resource'] - Name of the missing resource (e.g. "User").
   * @param {string|number} [id]           - Optional identifier that was looked up.
   *
   * @example
   *   throw new NotFoundError('User', 42);
   *   // message → "User with id 42 was not found"
   *
   * @example
   *   throw new NotFoundError();
   *   // message → "Resource was not found"
   */
  constructor(resource = 'Resource', id) {
    const message = id !== undefined
      ? `${resource} with id ${id} was not found`
      : `${resource} was not found`;

    super(message, 404, 'NOT_FOUND');
  }
}

// ---------------------------------------------------------------------------
// 422 Validation Error
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * Raised when client-supplied input fails validation rules.
   *
   * @param {string}   message          - Summary of what is invalid.
   * @param {Object[]} [fields=[]]      - Per-field detail objects.
   * @param {string}     fields[].field   - Name of the failing field.
   * @param {string}     fields[].message - Reason the field is invalid.
   *
   * @example
   *   throw new ValidationError('Invalid request body', [
   *     { field: 'email', message: 'must be a valid email address' },
   *     { field: 'age',   message: 'must be a positive integer' },
   *   ]);
   */
  constructor(message = 'Validation failed', fields = []) {
    super(message, 422, 'VALIDATION_ERROR');
    this.fields = fields;
  }
}

// ---------------------------------------------------------------------------
// 503 Database Error
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * Raised when a database operation fails.
   * The original low-level error is stored on `this.cause` so it can be
   * inspected by the error-handler for logging without leaking internals to
   * the client.
   *
   * @param {string} [message='A database error occurred'] - Public-safe description.
   * @param {Error}  [cause]                               - Original DB driver error.
   *
   * @example
   *   try {
   *     await db.query(sql);
   *   } catch (dbErr) {
   *     throw new DatabaseError('Failed to fetch users', dbErr);
   *   }
   */
  constructor(message = 'A database error occurred', cause) {
    super(message, 503, 'DATABASE_ERROR');
    if (cause instanceof Error) {
      this.cause = cause; // native Error#cause (Node 16.9+) / manual fallback
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 * Express application with centralised error handling.
 *
 * Error flow
 * ----------
 *  Route handlers / middleware throw (or next()) an AppError subclass.
 *  The errorHandler middleware at the bottom catches every error,
 *  normalises it, logs it, and sends a consistent JSON response.
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ─── Simulated in-memory data ────────────────────────────────────────────────

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── Routes ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Simple liveness probe — never throws.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 *
 * Throws:
 *  DatabaseError – if the data-layer call fails.
 */
app.get('/users', (req, res) => {
  // Simulate a data-layer call that could fail.
  // Replace the body of getUsersFromDb() with real DB logic as needed.
  const users = getUsersFromDb();
  res.json(users);
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 *
 * Throws:
 *  ValidationError – if :id is not a positive integer.
 *  NotFoundError   – if no user with that id exists.
 *  DatabaseError   – if the data-layer call fails.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user id', [
      { field: 'id', message: 'must be a positive integer' },
    ]);
  }

  const user = getUserByIdFromDb(id);

  if (!user) {
    throw new NotFoundError('User', id);
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 *
 * Throws:
 *  ValidationError – if name or email are missing / malformed.
 *  DatabaseError   – if the data-layer call fails.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body ?? {};

  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string') {
    fieldErrors.push({ field: 'email', message: 'is required and must be a string' });
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.push({ field: 'email', message: 'must be a valid email address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Request body contains invalid fields', fieldErrors);
  }

  const newUser = createUserInDb({ name: name.trim(), email });
  res.status(201).json(newUser);
});

// ─── 404 catch-all for unmatched routes ──────────────────────────────────────

/**
 * Must be registered AFTER all valid routes so it only fires when nothing
 * else matched.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Route ${req.method} ${req.path}`));
});

// ─── Centralised error-handling middleware ───────────────────────────────────

/**
 * errorHandler
 *
 * Express identifies a middleware as an error handler by its 4-argument
 * signature (err, req, res, next).  It must be registered last.
 *
 * Behaviour
 * ---------
 *  • Operational errors (AppError subclasses)
 *      → logged at warn level, client receives statusCode + JSON body.
 *  • Unexpected/programmer errors (generic Error or non-operational AppError)
 *      → logged at error level (including stack), client always gets 500 so
 *        no internal details leak.
 *
 * Response shape
 * --------------
 *  {
 *    "error": {
 *      "status":    <number>,
 *      "errorCode": <string>,
 *      "message":   <string>,
 *      "fields":    <array>   // only present on ValidationError
 *    }
 *  }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Determine whether this is a known operational error ───────────────────
  const isOperational = err instanceof AppError && err.isOperational;

  // ── Log ───────────────────────────────────────────────────────────────────
  if (isOperational) {
    // Known errors: concise one-liner is enough
    console.warn(
      `[${new Date().toISOString()}] ${err.name} ${err.statusCode} — ${err.message}`,
    );
  } else {
    // Unknown errors: include full stack so developers can diagnose them
    console.error(
      `[${new Date().toISOString()}] Unhandled error on ${req.method} ${req.path}:\n${err.stack || err}`,
    );
    // Also surface the root cause if one was attached (e.g. DatabaseError#cause)
    if (err.cause) {
      console.error('Caused by:', err.cause.stack || err.cause);
    }
  }

  // ── Build response ────────────────────────────────────────────────────────
  const statusCode = isOperational ? err.statusCode : 500;

  const body = {
    error: {
      status:    statusCode,
      errorCode: isOperational ? err.errorCode : 'INTERNAL_ERROR',
      message:   isOperational ? err.message   : 'An unexpected error occurred',
    },
  };

  // Attach per-field details for validation failures
  if (isOperational && err instanceof ValidationError && Array.isArray(err.fields)) {
    body.error.fields = err.fields;
  }

  res.status(statusCode).json(body);
});

// ─── Simulated data-layer helpers ────────────────────────────────────────────
// In a real application these would live in a separate service/repository layer
// and interact with an actual database. They are kept inline here purely for
// demonstration purposes and to show where DatabaseError should be thrown.

function getUsersFromDb() {
  try {
    // Real implementation: return await db.query('SELECT …');
    return USERS;
  } catch (dbErr) {
    throw new DatabaseError('Failed to retrieve users', dbErr);
  }
}

function getUserByIdFromDb(id) {
  try {
    // Real implementation: return await db.query('SELECT … WHERE id = $1', [id]);
    return USERS.find((u) => u.id === id) ?? null;
  } catch (dbErr) {
    throw new DatabaseError(`Failed to retrieve user ${id}`, dbErr);
  }
}

function createUserInDb(data) {
  try {
    // Real implementation: return await db.query('INSERT INTO …');
    const newUser = { id: USERS.length + 1, ...data };
    USERS.push(newUser);
    return newUser;
  } catch (dbErr) {
    throw new DatabaseError('Failed to create user', dbErr);
  }
}

// ─── Start server (skipped when required as a module, e.g. in tests) ─────────

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

