/**
 * errors.js
 *
 * Centralised application error hierarchy.
 *
 * Every class extends the built-in Error and carries:
 *   - statusCode  – the HTTP status that should be sent to the client
 *   - code        – a stable machine-readable string (useful for API consumers)
 *   - isOperational – true for "expected" errors (validation, not-found, …)
 *                     false-ish (i.e. omitted / default false) for programmer
 *                     mistakes so the error handler can distinguish between
 *                     the two and decide whether to restart the process.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message       Human-readable description of the error.
   * @param {number}  statusCode    HTTP status code (default 500).
   * @param {string}  code          Machine-readable error code.
   * @param {boolean} isOperational Whether this is an expected / handled error.
   */
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR', isOperational = true) {
    super(message);

    // Restore the correct constructor name so stack-traces are readable.
    this.name = this.constructor.name;
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean V8 stack trace that starts at the call site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Returns a plain-object representation safe to send in a JSON response.
   * Sensitive internals (stack, isOperational) are intentionally omitted.
   */
  toJSON() {
    return {
      error: {
        code: this.code,
        message: this.message,
        statusCode: this.statusCode,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 404 – resource not found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource] Optional name of the resource that was not found
   *                            (e.g. "User", "Order").  When supplied the
   *                            message is generated automatically.
   * @param {string} [message]  Override the generated message entirely.
   */
  constructor(resource, message) {
    const msg = message || (resource ? `${resource} not found` : 'Resource not found');
    super(msg, 404, 'NOT_FOUND');
    this.resource = resource || null;
  }
}

// ---------------------------------------------------------------------------
// 422 – semantic / business-rule validation failure
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}   message Human-readable summary of what failed.
   * @param {Object[]} [errors] Optional array of field-level error objects,
   *                            e.g. [{ field: 'email', message: 'is required' }].
   */
  constructor(message, errors = []) {
    super(message, 422, 'VALIDATION_ERROR');
    this.errors = errors; // field-level detail, may be empty
  }

  /** Extend the base JSON shape with field-level detail. */
  toJSON() {
    const base = super.toJSON();
    if (this.errors.length > 0) {
      base.error.errors = this.errors;
    }
    return base;
  }
}

// ---------------------------------------------------------------------------
// 503 – database / persistence layer failure
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]  Human-readable description.
   * @param {Error}  [cause]    The original low-level DB error, stored under
   *                            `this.cause` so it can be inspected in logs
   *                            without being leaked to the client.
   */
  constructor(message = 'A database error occurred', cause = null) {
    // isOperational = false → signals that the system may be in a bad state
    // and the process-level uncaught-exception handler may want to restart.
    super(message, 503, 'DATABASE_ERROR', false);
    this.cause = cause; // original error — never serialised into toJSON()
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
};

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe – no error paths needed here.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns all users.
 * Throws NotFoundError when the user list is empty, and DatabaseError when
 * the persistence layer is unavailable.
 */
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  if (!users || users.length === 0) {
    throw new NotFoundError('Users');
  }

  res.json(users);
});

/**
 * GET /users/:id
 * Returns a single user by ID.
 * Throws ValidationError for a non-numeric ID, NotFoundError when the user
 * does not exist, and DatabaseError for persistence failures.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user ID', [
      { field: 'id', message: 'must be a positive integer' },
    ]);
  }

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find((u) => u.id === id);

  if (!user) {
    throw new NotFoundError('User');
  }

  res.json(user);
});

/**
 * POST /users
 * Creates a new user.
 * Throws ValidationError when required fields are missing or malformed, and
 * DatabaseError when the record cannot be persisted.
 */
app.post('/users', (req, res) => {
  const { name, email } = req.body || {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'is required and must be a non-empty string' });
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    fieldErrors.push({ field: 'email', message: 'is required and must be a valid email address' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('Request body contains invalid fields', fieldErrors);
  }

  // Simulate persistence — replace with a real DB call in production.
  const newUser = { id: Date.now(), name: name.trim(), email: email.trim() };
  res.status(201).json(newUser);
});

// ---------------------------------------------------------------------------
// 404 catch-all — must be registered AFTER all real routes
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  next(new NotFoundError('Route', `Cannot ${req.method} ${req.path}`));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
//
// Express identifies error-handling middleware by its four-argument signature
// (err, req, res, next) and only invokes it when next(err) is called or when
// a synchronous throw occurs inside a route handler.
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── 1. Determine whether this is one of our own typed errors ────────────
  const isAppError = err instanceof AppError;

  // ── 2. Log the error ────────────────────────────────────────────────────
  // Always log the full error (including stack) on the server so engineers
  // can debug, but only expose safe details to the client.
  if (isAppError && err.isOperational) {
    // Expected, handled error — info-level log is sufficient.
    console.error(`[${err.code}] ${err.message}`);
  } else {
    // Unexpected / programmer error — log the full stack for post-mortem.
    console.error('Unexpected error:', err);
  }

  // ── 3. Build the response ───────────────────────────────────────────────
  if (isAppError) {
    // Use the structured toJSON() defined on the error class.
    return res.status(err.statusCode).json(err.toJSON());
  }

  // Fallback for any error that was not thrown as an AppError subclass
  // (e.g. a JSON.parse failure thrown by express.json()).
  const statusCode = typeof err.status === 'number' ? err.status : 500;
  return res.status(statusCode).json({
    error: {
      code: 'INTERNAL_ERROR',
      message:
        process.env.NODE_ENV === 'production'
          ? 'An unexpected error occurred'
          : err.message || 'An unexpected error occurred',
      statusCode,
    },
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

'use strict';

/**
 * app.test.js
 *
 * Integration tests for app.js and unit tests for errors.js.
 *
 * Run with:  npx jest  (or  node --test  if you swap to Node's built-in runner)
 */

const request = require('supertest');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');
const app = require('./app');

// ---------------------------------------------------------------------------
// Unit tests – error classes (errors.js)
// ---------------------------------------------------------------------------

describe('Error classes (errors.js)', () => {

  // ── AppError ──────────────────────────────────────────────────────────────
  describe('AppError', () => {
    test('stores message, statusCode, code, and isOperational', () => {
      const err = new AppError('Something broke', 500, 'INTERNAL_ERROR', true);

      expect(err).toBeInstanceOf(Error);
      expect(err).toBeInstanceOf(AppError);
      expect(err.message).toBe('Something broke');
      expect(err.statusCode).toBe(500);
      expect(err.code).toBe('INTERNAL_ERROR');
      expect(err.isOperational).toBe(true);
    });

    test('name is set to the constructor name', () => {
      const err = new AppError('test');
      expect(err.name).toBe('AppError');
    });

    test('toJSON() returns the correct shape', () => {
      const err = new AppError('test error', 500, 'TEST_CODE');
      expect(err.toJSON()).toEqual({
        error: {
          code: 'TEST_CODE',
          message: 'test error',
          statusCode: 500,
        },
      });
    });

    test('toJSON() does NOT expose stack or isOperational', () => {
      const json = new AppError('test').toJSON();
      expect(json.error).not.toHaveProperty('stack');
      expect(json.error).not.toHaveProperty('isOperational');
    });

    test('defaults: statusCode=500, code=INTERNAL_ERROR, isOperational=true', () => {
      const err = new AppError('default test');
      expect(err.statusCode).toBe(500);
      expect(err.code).toBe('INTERNAL_ERROR');
      expect(err.isOperational).toBe(true);
    });
  });

  // ── NotFoundError ─────────────────────────────────────────────────────────
  describe('NotFoundError', () => {
    test('sets statusCode=404 and code=NOT_FOUND', () => {
      const err = new NotFoundError('User');
      expect(err.statusCode).toBe(404);
      expect(err.code).toBe('NOT_FOUND');
    });

    test('auto-generates message from resource name', () => {
      const err = new NotFoundError('Order');
      expect(err.message).toBe('Order not found');
    });

    test('uses generic message when no resource is provided', () => {
      const err = new NotFoundError();
      expect(err.message).toBe('Resource not found');
    });

    test('accepts an explicit message override', () => {
      const err = new NotFoundError('Product', 'The requested product is unavailable');
      expect(err.message).toBe('The requested product is unavailable');
    });

    test('stores resource name', () => {
      const err = new NotFoundError('Widget');
      expect(err.resource).toBe('Widget');
    });

    test('resource is null when not supplied', () => {
      const err = new NotFoundError();
      expect(err.resource).toBeNull();
    });

    test('is an instance of AppError', () => {
      expect(new NotFoundError()).toBeInstanceOf(AppError);
    });
  });

  // ── ValidationError ───────────────────────────────────────────────────────
  describe('ValidationError', () => {
    test('sets statusCode=422 and code=VALIDATION_ERROR', () => {
      const err = new ValidationError('Bad input');
      expect(err.statusCode).toBe(422);
      expect(err.code).toBe('VALIDATION_ERROR');
    });

    test('stores field-level errors', () => {
      const fieldErrors = [{ field: 'email', message: 'is required' }];
      const err = new ValidationError('Validation failed', fieldErrors);
      expect(err.errors).toEqual(fieldErrors);
    });

    test('defaults to an empty errors array', () => {
      const err = new ValidationError('Something invalid');
      expect(err.errors).toEqual([]);
    });

    test('toJSON() includes errors array when present', () => {
      const fieldErrors = [{ field: 'name', message: 'is required' }];
      const err = new ValidationError('Validation failed', fieldErrors);
      expect(err.toJSON()).toEqual({
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Validation failed',
          statusCode: 422,
          errors: fieldErrors,
        },
      });
    });

    test('toJSON() omits errors key when array is empty', () => {
      const err = new ValidationError('Validation failed');
      expect(err.toJSON().error).not.toHaveProperty('errors');
    });

    test('is an instance of AppError', () => {
      expect(new ValidationError('test')).toBeInstanceOf(AppError);
    });
  });

  // ── DatabaseError ─────────────────────────────────────────────────────────
  describe('DatabaseError', () => {
    test('sets statusCode=503 and code=DATABASE_ERROR', () => {
      const err = new DatabaseError();
      expect(err.statusCode).toBe(503);
      expect(err.code).toBe('DATABASE_ERROR');
    });

    test('isOperational is false', () => {
      const err = new DatabaseError();
      expect(err.isOperational).toBe(false);
    });

    test('has a sensible default message', () => {
      const err = new DatabaseError();
      expect(err.message).toBe('A database error occurred');
    });

    test('accepts a custom message', () => {
      const err = new DatabaseError('Connection timed out');
      expect(err.message).toBe('Connection timed out');
    });

    test('stores the original cause without exposing it in toJSON()', () => {
      const cause = new Error('pg: connection refused');
      const err = new DatabaseError('DB unavailable', cause);
