      expect(JSON.stringify(json)).not.toContain('pg: connection refused');
    });

    test('is an instance of AppError', () => {
      expect(new DatabaseError()).toBeInstanceOf(AppError);
    });
  });
});

// ---------------------------------------------------------------------------
// Integration tests – Express routes (app.js)
// ---------------------------------------------------------------------------

describe('Express routes (app.js)', () => {

  // ── GET /health ───────────────────────────────────────────────────────────
  describe('GET /health', () => {
    test('returns 200 with status=ok and a timestamp', async () => {
      const res = await request(app).get('/health');
      expect(res.status).toBe(200);
      expect(res.body.status).toBe('ok');
