        .post('/users')
        .send({ name: '   ', email: 'valid@example.com' });

      expect(res.status).toBe(422);
      expect(res.body.error.errors).toEqual(
        expect.arrayContaining([expect.objectContaining({ field: 'name' })])
      );
    });
  });

  // ── 404 catch-all ─────────────────────────────────────────────────────────
  describe('404 catch-all', () => {
    test('returns 404 with NOT_FOUND for an unknown GET route', async () => {
      const res = await request(app).get('/this-does-not-exist');
      expect(res.status).toBe(404);
      expect(res.body.error.code).toBe('NOT_FOUND');
    });

    test('returns 404 with NOT_FOUND for an unknown POST route', async () => {
      const res = await request(app).post('/unknown');
      expect(res.status).toBe(404);
      expect(res.body.error.code).toBe('NOT_FOUND');
