/**
 * errors.js
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error and adds:
 *   - statusCode  – HTTP status code sent to the client
 *   - isOperational – true  → known/expected error (safe to expose message)
 *                     false → programmer error (suppress detail in production)
 */

'use strict';

// ─── Base ────────────────────────────────────────────────────────────────────

class AppError extends Error {
  /**
   * @param {string}  message       - Human-readable description.
   * @param {number}  statusCode    - HTTP status code.
   * @param {string}  [errorCode]   - Machine-readable code, e.g. "NOT_FOUND".
   * @param {boolean} [isOperational=true]
   */
  constructor(message, statusCode, errorCode, isOperational = true) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.errorCode   = errorCode || this.constructor.name.toUpperCase().replace('ERROR', '_ERROR');
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── 404 Not Found ───────────────────────────────────────────────────────────

/**
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Product ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message='Resource not found']
   * @param {string} [errorCode='NOT_FOUND']
   */
  constructor(message = 'Resource not found', errorCode = 'NOT_FOUND') {
    super(message, 404, errorCode);
  }
}

// ─── 422 Validation ──────────────────────────────────────────────────────────

/**
 * Thrown when client-supplied data fails validation.
 * Optionally carries a `fields` map of per-field error messages.
 *
 * @example
 *   throw new ValidationError('Invalid payload');
 *   throw new ValidationError('Invalid payload', { email: 'must be a valid email' });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message='Validation failed']
   * @param {Object} [fields={}]   - Optional per-field detail: { fieldName: 'reason' }
   * @param {string} [errorCode='VALIDATION_ERROR']
   */
  constructor(message = 'Validation failed', fields = {}, errorCode = 'VALIDATION_ERROR') {
    super(message, 422, errorCode);
    this.fields = fields;
  }
}

// ─── 503 Database ────────────────────────────────────────────────────────────

/**
 * Thrown when a database operation fails.
 * `cause` preserves the original low-level error without leaking it to clients.
 *
 * @example
 *   throw new DatabaseError('Could not fetch users', originalPgError);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message='A database error occurred']
   * @param {Error}  [cause=null]  - Original driver/ORM error (never sent to client).
   * @param {string} [errorCode='DATABASE_ERROR']
   */
  constructor(
    message = 'A database error occurred',
    cause   = null,
    errorCode = 'DATABASE_ERROR',
  ) {
    // DatabaseError is a 503 – the server could not complete the request.
    // isOperational = true so the process does not crash, but message is
    // intentionally generic to avoid leaking DB internals.
    super(message, 503, errorCode, true);
    this.cause = cause; // available for server-side logging, never serialised
  }
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

/**
 * app.js
 * Express application with centralised error handling.
 *
 * Error flow
 * ──────────
 *  Route/middleware throws (or calls next(err))
 *      │
 *      ▼
 *  errorHandler middleware (bottom of file)
 *      │
 *      ├─ AppError (operational) → structured JSON response
 *      └─ Unknown error          → 500 + safe "Internal server error" message
 */

'use strict';

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

app.use(express.json()); // parse JSON request bodies

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Wraps an async route handler so that any rejected promise / thrown error is
 * forwarded to Express's next(err) automatically.
 * Eliminates the need for try/catch boilerplate in every route.
 *
 * @param {Function} fn - async (req, res, next) => {}
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ─── In-memory data store (stand-in for a real DB) ───────────────────────────

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

/** Simulate async DB access; rejects when forceError=true for demo purposes. */
const db = {
  getAllUsers: async ({ forceError = false } = {}) => {
    if (forceError) {
      throw new Error('Connection refused'); // raw driver error
    }
    return users;
  },

  getUserById: async (id, { forceError = false } = {}) => {
    if (forceError) {
      throw new Error('Connection refused');
    }
    return users.find((u) => u.id === id) || null;
  },

  createUser: async (data, { forceError = false } = {}) => {
    if (forceError) {
      throw new Error('Unique constraint violation');
    }
    const newUser = { id: users.length + 1, ...data };
    users.push(newUser);
    return newUser;
  },
};

// ─── Routes ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Basic liveness probe – always returns 200 while the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns all users.
 * Query param: ?simulateDbError=true  → exercises DatabaseError handling.
 */
app.get('/users', asyncHandler(async (req, res) => {
  const forceError = req.query.simulateDbError === 'true';

  let allUsers;
  try {
    allUsers = await db.getAllUsers({ forceError });
  } catch (cause) {
    // Wrap the raw driver error so internals are never exposed to the client.
    throw new DatabaseError('Failed to retrieve users', cause);
  }

  res.json(allUsers);
}));

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 * Throws NotFoundError when the user does not exist.
 * Throws ValidationError when :id is not a positive integer.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  // ── Validation ──────────────────────────────────────────────────────────
  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user id', {
      id: 'Must be a positive integer',
    });
  }

  // ── DB access ────────────────────────────────────────────────────────────
  let user;
  try {
    const forceError = req.query.simulateDbError === 'true';
    user = await db.getUserById(id, { forceError });
  } catch (cause) {
    throw new DatabaseError(`Failed to retrieve user ${id}`, cause);
  }

  // ── Not found ────────────────────────────────────────────────────────────
  if (!user) {
    throw new NotFoundError(`User with id ${id} not found`, 'USER_NOT_FOUND');
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 * Body: { name: string, email: string }
 *
 * Throws ValidationError for missing / malformed fields.
 * Throws DatabaseError if the db layer fails.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body || {};

  // ── Validation ──────────────────────────────────────────────────────────
  const fieldErrors = {};

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.name = 'name is required and must be a non-empty string';
  }

  if (!email || typeof email !== 'string') {
    fieldErrors.email = 'email is required and must be a string';
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fieldErrors.email = 'email must be a valid email address';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Request body validation failed', fieldErrors);
  }

  // ── DB access ────────────────────────────────────────────────────────────
  let newUser;
  try {
    const forceError = req.query.simulateDbError === 'true';
    newUser = await db.createUser({ name: name.trim(), email }, { forceError });
  } catch (cause) {
    // Rethrow DatabaseErrors that were already wrapped (shouldn't happen here,
    // but guards against accidental double-wrapping).
    if (cause instanceof DatabaseError) throw cause;
    throw new DatabaseError('Failed to create user', cause);
  }

  res.status(201).json(newUser);
}));

// ─── 404 catch-all ───────────────────────────────────────────────────────────

/**
 * Matches any request that fell through all defined routes.
 * Must be placed AFTER all route definitions.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`, 'ROUTE_NOT_FOUND'));
});

// ─── Centralised error handler ───────────────────────────────────────────────

/**
 * Express identifies a function with four parameters (err, req, res, next) as
 * an error-handling middleware.  It must be registered last.
 *
 * Behaviour
 * ─────────
 *  • Operational AppErrors  → log lightly, send structured JSON with real message.
 *  • Unknown/programmer errors → log fully (stack), send safe 500 response.
 *  • Never leaks stack traces or raw DB errors to the client.
 *
 * Response shape
 * ──────────────
 *  {
 *    "error": {
 *      "status":    <http status code>,
 *      "errorCode": <machine-readable string>,
 *      "message":   <human-readable string>,
 *      "fields":    <object – ValidationError only>   // omitted otherwise
 *    }
 *  }
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ── Determine whether this is a known operational error ──────────────────
  const isOperational = err instanceof AppError && err.isOperational;

  // ── Logging ──────────────────────────────────────────────────────────────
  if (isOperational) {
    // Expected errors: concise one-liner is enough.
    console.warn(`[${err.name}] ${err.statusCode} — ${err.message}`);
  } else {
    // Unexpected errors: full stack for post-mortem debugging.
    console.error('[UnhandledError]', err);
  }

  // ── Determine response values ─────────────────────────────────────────────
  const statusCode = isOperational ? err.statusCode : 500;
  const errorCode  = isOperational ? err.errorCode  : 'INTERNAL_SERVER_ERROR';

  // In production, never expose internals of unrecognised errors.
  const message = isOperational
    ? err.message
    : 'An unexpected error occurred. Please try again later.';

  // ── Build the response payload ────────────────────────────────────────────
  const payload = {
    error: {
      status:    statusCode,
      errorCode,
      message,
    },
  };

  // Attach per-field details for validation errors only.
  if (isOperational && err instanceof ValidationError && err.fields) {
    payload.error.fields = err.fields;
  }

  // Attach the database cause message in non-production for easier debugging.
  if (
    isOperational &&
    err instanceof DatabaseError &&
    err.cause &&
    process.env.NODE_ENV !== 'production'
  ) {
    payload.error.detail = err.cause.message;
  }

  res.status(statusCode).json(payload);
});

// ─── Start ───────────────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

