# Verify the error classes in isolation — no network needed
node - <<'EOF'
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const tests = [];
const assert = (label, condition) => {
  tests.push({ label, pass: !!condition });
};

// ── AppError base ──────────────────────────────────────────────────────────
const base = new AppError('base msg', 400, 'BASE_CODE');
assert('AppError message',        base.message     === 'base msg');
assert('AppError statusCode',     base.statusCode  === 400);
assert('AppError errorCode',      base.errorCode   === 'BASE_CODE');
assert('AppError isOperational',  base.isOperational === true);
assert('AppError instanceof',     base instanceof AppError);
assert('AppError instanceof Error', base instanceof Error);

// ── NotFoundError ──────────────────────────────────────────────────────────
const nfe = new NotFoundError('User not found', 'USER_NOT_FOUND');
assert('NotFoundError statusCode',   nfe.statusCode  === 404);
assert('NotFoundError errorCode',    nfe.errorCode   === 'USER_NOT_FOUND');
assert('NotFoundError message',      nfe.message     === 'User not found');
assert('NotFoundError isOperational',nfe.isOperational === true);
assert('NotFoundError instanceof AppError', nfe instanceof AppError);

// defaults
const nfeD = new NotFoundError();
assert('NotFoundError default message',   nfeD.message   === 'Resource not found');
assert('NotFoundError default errorCode', nfeD.errorCode === 'NOT_FOUND');

// ── ValidationError ────────────────────────────────────────────────────────
const fields = { email: 'invalid email' };
const ve = new ValidationError('Validation failed', fields);
assert('ValidationError statusCode',    ve.statusCode === 422);
assert('ValidationError errorCode',     ve.errorCode  === 'VALIDATION_ERROR');
assert('ValidationError fields',        ve.fields.email === 'invalid email');
assert('ValidationError isOperational', ve.isOperational === true);
assert('ValidationError instanceof AppError', ve instanceof AppError);

// defaults
const veD = new ValidationError();
assert('ValidationError default message', veD.message === 'Validation failed');
assert('ValidationError default fields',  JSON.stringify(veD.fields) === '{}');

// ── DatabaseError ──────────────────────────────────────────────────────────
const cause = new Error('pg: connection refused');
const dbe = new DatabaseError('DB failed', cause);
assert('DatabaseError statusCode',    dbe.statusCode === 503);
assert('DatabaseError errorCode',     dbe.errorCode  === 'DATABASE_ERROR');
assert('DatabaseError cause',         dbe.cause === cause);
assert('DatabaseError isOperational', dbe.isOperational === true);
assert('DatabaseError instanceof AppError', dbe instanceof AppError);

// defaults
const dbeD = new DatabaseError();
assert('DatabaseError default message', dbeD.message === 'A database error occurred');
assert('DatabaseError default cause',   dbeD.cause   === null);

// ── instanceof cross-checks ────────────────────────────────────────────────
assert('NotFoundError NOT instanceof ValidationError', !(nfe instanceof ValidationError));
assert('ValidationError NOT instanceof NotFoundError', !(ve  instanceof NotFoundError));
assert('DatabaseError NOT instanceof NotFoundError',   !(dbe instanceof NotFoundError));

// ── Stack traces present ───────────────────────────────────────────────────
assert('NotFoundError has stack',   typeof nfe.stack === 'string');
assert('ValidationError has stack', typeof ve.stack  === 'string');
assert('DatabaseError has stack',   typeof dbe.stack === 'string');

// ── name property ──────────────────────────────────────────────────────────
assert('NotFoundError name',   nfe.name === 'NotFoundError');
assert('ValidationError name', ve.name  === 'ValidationError');
assert('DatabaseError name',   dbe.name === 'DatabaseError');

// ── Report ─────────────────────────────────────────────────────────────────
const failed = tests.filter(t => !t.pass);
const passed = tests.filter(t =>  t.pass);
console.log(`\nResults: ${passed.length} passed, ${failed.length} failed out of ${tests.length} tests\n`);
passed.forEach(t => console.log(`  ✓ ${t.label}`));
if (failed.length) {
  console.log('\nFailed:');
  failed.forEach(t => console.log(`  ✗ ${t.label}`));
  process.exit(1);
}
EOF

