/**
 * errors.js
 *
 * Centralised application error classes.
 *
 * Every class extends the base AppError, which carries:
 *   - message    : human-readable description
 *   - statusCode : HTTP status code that should be sent to the client
 *   - code       : machine-readable error code for programmatic handling
 *   - isOperational : true  → expected, "safe" error (bad input, missing row …)
 *                     false → unexpected, programmer error (should crash / alert)
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message        - Human-readable error description.
   * @param {number}  statusCode     - HTTP status code.
   * @param {string}  code           - Machine-readable error code.
   * @param {boolean} isOperational  - Whether this is a known, safe error.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Restore the correct prototype chain so `instanceof` checks work after
    // TypeScript / Babel transpilation.
    Object.setPrototypeOf(this, new.target.prototype);

    this.name        = this.constructor.name;
    this.statusCode  = statusCode;
    this.code        = code;
    this.isOperational = isOperational;

    // Capture a clean stack trace that starts at the call-site, not here.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – resource not found
// ---------------------------------------------------------------------------

class NotFoundError extends AppError {
  /**
   * @param {string} [resource] - Optional label for the missing resource,
   *                              e.g. "User", "Order".  Defaults to "Resource".
   * @param {string} [id]       - Optional identifier that was looked up.
   */
  constructor(resource = 'Resource', id = null) {
    const message = id
      ? `${resource} with id '${id}' was not found.`
      : `${resource} was not found.`;

    super(message, 404, 'NOT_FOUND');
    this.resource = resource;
    this.resourceId = id;
  }
}

// ---------------------------------------------------------------------------
// 422 – validation / bad input
// ---------------------------------------------------------------------------

class ValidationError extends AppError {
  /**
   * @param {string}   message - Summary of what failed validation.
   * @param {Object[]} [errors] - Optional array of per-field error objects,
   *                              e.g. [{ field: 'email', message: 'Invalid format' }].
   */
  constructor(message = 'Validation failed.', errors = []) {
    super(message, 422, 'VALIDATION_ERROR');
    // Expose individual field errors so clients can display them inline.
    this.errors = errors;
  }
}

// ---------------------------------------------------------------------------
// 503 – database / persistence layer failure
// ---------------------------------------------------------------------------

class DatabaseError extends AppError {
  /**
   * @param {string} [message]  - Human-readable description.
   * @param {Error}  [original] - The underlying driver / ORM error, kept for
   *                              server-side logging but never sent to clients.
   */
  constructor(message = 'A database error occurred.', original = null) {
    // DatabaseError is marked non-operational: it is unexpected and should
    // trigger alerts / process-level handling in production.
    super(message, 503, 'DATABASE_ERROR', false);
    this.original = original;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

/**
 * app.js
 *
 * Express application with centralised error handling.
 *
 * Key architectural decisions
 * ───────────────────────────
 * 1. All route handlers throw (or pass to next()) an AppError subclass instead
 *    of calling res.status().json() inline.  This keeps error-response shaping
 *    in one place.
 * 2. A dedicated errorHandler middleware (registered last) translates every
 *    AppError into a consistent JSON envelope, and handles unexpected errors
 *    gracefully without leaking stack traces to clients.
 * 3. A catch-all 404 route sits between the real routes and the error handler
 *    so that unmatched requests also receive the standard error envelope.
 */

const express = require('express');
const {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
} = require('./errors');

const app = express();

// ---------------------------------------------------------------------------
// Request parsing
// ---------------------------------------------------------------------------

app.use(express.json());

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe — always returns 200 when the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns a static list of users.
 * Demonstrates: no error path here, but the handler is async-safe via the
 * asyncHandler wrapper below if you add DB calls later.
 */
app.get('/users', asyncHandler(async (req, res) => {
  // In a real application this would be a DB call; a DatabaseError would be
  // thrown if the query failed.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  res.json(users);
}));

/**
 * GET /users/:id
 * Returns a single user by id.
 * Demonstrates: NotFoundError when the resource does not exist.
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const id = Number(req.params.id);

  if (!Number.isInteger(id) || id <= 0) {
    throw new ValidationError('Invalid user id.', [
      { field: 'id', message: 'Must be a positive integer.' },
    ]);
  }

  // Simulated data store — replace with a real DB call.
  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com' },
    2: { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  };

  const user = users[id];

  if (!user) {
    throw new NotFoundError('User', id);
  }

  res.json(user);
}));

/**
 * POST /users
 * Creates a new user.
 * Demonstrates: ValidationError for missing / invalid fields.
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body ?? {};
  const fieldErrors = [];

  if (!name || typeof name !== 'string' || name.trim() === '') {
    fieldErrors.push({ field: 'name', message: 'Name is required.' });
  }

  if (!email || typeof email !== 'string' || !email.includes('@')) {
    fieldErrors.push({ field: 'email', message: 'A valid email is required.' });
  }

  if (fieldErrors.length > 0) {
    throw new ValidationError('User validation failed.', fieldErrors);
  }

  // Simulated creation — replace with a real DB call.
  // A DatabaseError would be thrown here if the INSERT failed.
  const newUser = { id: Date.now(), name: name.trim(), email };

  res.status(201).json(newUser);
}));

// ---------------------------------------------------------------------------
// 404 catch-all  (must come after all real routes)
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  next(new NotFoundError(`Route '${req.method} ${req.path}'`));
});

// ---------------------------------------------------------------------------
// Centralised error handler  (must be last, and must have 4 parameters)
// ---------------------------------------------------------------------------

/**
 * errorHandler
 *
 * Converts any error thrown (or passed to next()) anywhere in the application
 * into a consistent JSON response envelope:
 *
 *   {
 *     "error": {
 *       "code":    "NOT_FOUND",          // machine-readable code
 *       "message": "User … not found.",  // human-readable description
 *       "errors":  [...]                 // optional per-field details
 *     }
 *   }
 *
 * Rules:
 *   - AppError subclasses  → use their own statusCode / code.
 *   - Non-operational errors (e.g. DatabaseError) → 503, generic message so
 *     internal details are not leaked to clients; full error is logged.
 *   - Completely unknown errors → 500, generic message; full error is logged.
 *   - Stack traces are only included when NODE_ENV === 'development'.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  // ── Operational AppError (e.g. NotFoundError, ValidationError) ────────────
  if (err instanceof AppError && err.isOperational) {
    const body = {
      error: {
        code:    err.code,
        message: err.message,
      },
    };

    // Attach per-field validation details when present.
    if (err instanceof ValidationError && err.errors.length > 0) {
      body.error.errors = err.errors;
    }

    if (isDev) {
      body.error.stack = err.stack;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Non-operational AppError (e.g. DatabaseError) ────────────────────────
  if (err instanceof AppError && !err.isOperational) {
    // Log the full error server-side (swap console.error for your logger).
    console.error('[Non-operational error]', {
      code:    err.code,
      message: err.message,
      original: err.original ?? null,
      stack:   err.stack,
    });

    const body = {
      error: {
        code:    err.code,
        message: 'An internal server error occurred. Please try again later.',
      },
    };

    if (isDev) {
      body.error.detail = err.message;
      body.error.stack  = err.stack;
    }

    return res.status(err.statusCode).json(body);
  }

  // ── Completely unknown / programmer errors ────────────────────────────────
  console.error('[Unhandled error]', err);

  const body = {
    error: {
      code:    'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred. Please try again later.',
    },
  };

  if (isDev) {
    body.error.detail = err.message;
    body.error.stack  = err.stack;
  }

  return res.status(500).json(body);
});

// ---------------------------------------------------------------------------
// Utility – async route wrapper
// ---------------------------------------------------------------------------

/**
 * asyncHandler
 *
 * Wraps an async route handler so that any rejected promise or thrown error
 * is automatically forwarded to Express's next(err) without needing a
 * try/catch in every route.
 *
 * Usage:
 *   app.get('/path', asyncHandler(async (req, res) => { ... }));
 *
 * @param  {Function} fn - Async route handler.
 * @returns {Function}   Express-compatible middleware.
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = process.env.PORT ?? 3000;

/* istanbul ignore next */
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

