'use strict';
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let passed = 0;
let failed = 0;

function assert(condition, label) {
  if (condition) {
    console.log(`  ✓ ${label}`);
    passed++;
  } else {
    console.error(`  ✗ FAIL: ${label}`);
    failed++;
  }
}

// ── AppError base ────────────────────────────────────────────────────────────
console.log('\nAppError');
const base = new AppError('base msg', 400, 'BASE_CODE');
assert(base instanceof Error,    'extends Error');
assert(base instanceof AppError, 'instanceof AppError');
assert(base.message     === 'base msg',  'message set');
assert(base.statusCode  === 400,         'statusCode set');
assert(base.code        === 'BASE_CODE', 'code set');
assert(base.isOperational === true,      'isOperational defaults to true');
assert(base.name        === 'AppError',  'name is class name');
assert(typeof base.stack === 'string',   'stack is a string');

// ── NotFoundError ────────────────────────────────────────────────────────────
console.log('\nNotFoundError');
const nf1 = new NotFoundError('User', 42);
assert(nf1 instanceof AppError,      'instanceof AppError');
assert(nf1 instanceof NotFoundError, 'instanceof NotFoundError');
assert(nf1.statusCode  === 404,      'statusCode 404');
assert(nf1.code        === 'NOT_FOUND', 'code NOT_FOUND');
assert(nf1.isOperational === true,   'isOperational true');
assert(nf1.resource    === 'User',   'resource stored');
assert(nf1.resourceId  === 42,       'resourceId stored');
assert(nf1.message === "User with id '42' was not found.", 'message with id');

const nf2 = new NotFoundError('Order');
assert(nf2.message === 'Order was not found.', 'message without id');
assert(nf2.resourceId === null, 'resourceId null when omitted');

const nf3 = new NotFoundError();
assert(nf3.message === 'Resource was not found.', 'default resource label');

// ── ValidationError ──────────────────────────────────────────────────────────
console.log('\nValidationError');
const ve = new ValidationError('Val failed.', [
  { field: 'email', message: 'Invalid format' },
]);
assert(ve instanceof AppError,         'instanceof AppError');
assert(ve instanceof ValidationError,  'instanceof ValidationError');
assert(ve.statusCode  === 422,         'statusCode 422');
assert(ve.code        === 'VALIDATION_ERROR', 'code VALIDATION_ERROR');
assert(ve.isOperational === true,      'isOperational true');
assert(Array.isArray(ve.errors),       'errors is array');
assert(ve.errors.length === 1,         'one field error');
assert(ve.errors[0].field === 'email', 'field name preserved');

const veDefault = new ValidationError();
assert(veDefault.message === 'Validation failed.', 'default message');
assert(veDefault.errors.length === 0,              'default errors empty');

// ── DatabaseError ────────────────────────────────────────────────────────────
console.log('\nDatabaseError');
const origErr = new Error('connection refused');
const de = new DatabaseError('DB failed.', origErr);
assert(de instanceof AppError,       'instanceof AppError');
assert(de instanceof DatabaseError,  'instanceof DatabaseError');
assert(de.statusCode  === 503,       'statusCode 503');
assert(de.code        === 'DATABASE_ERROR', 'code DATABASE_ERROR');
assert(de.isOperational === false,   'isOperational false (non-operational)');
assert(de.original === origErr,      'original error stored');

const deDefault = new DatabaseError();
assert(deDefault.message  === 'A database error occurred.', 'default message');
assert(deDefault.original === null,  'original null when omitted');

// ── Inheritance / instanceof chain ──────────────────────────────────────────
console.log('\nInheritance');
assert(!(new NotFoundError()  instanceof ValidationError), 'NotFound not ValidationError');
assert(!(new ValidationError() instanceof NotFoundError),  'Validation not NotFoundError');
assert(!(new DatabaseError()  instanceof ValidationError), 'Database not ValidationError');

// ── Summary ──────────────────────────────────────────────────────────────────
console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);
EOF

