/**
 * Integration-style tests for the errorHandler and asyncHandler extracted
 * from app.js – runs without Express installed by simulating req/res/next.
 */
'use strict';

const {
  AppError,
  NotFoundError,
  ValidationError,
  DatabaseError,
} = require('./errors');

let passed = 0;
let failed = 0;

function assert(condition, label) {
  if (condition) {
    console.log(`  ✓ ${label}`);
    passed++;
  } else {
    console.error(`  ✗ FAIL: ${label}`);
    failed++;
  }
}

// ── Helpers ──────────────────────────────────────────────────────────────────

/** Minimal mock response that captures status + json calls. */
function mockRes() {
  const r = { _status: null, _body: null };
  r.status = (code) => { r._status = code; return r; };
  r.json   = (body) => { r._body  = body; return r; };
  return r;
}

/** Read the errorHandler function straight out of app.js source without
 *  requiring Express – we parse it as a module-level export shim. */
function buildErrorHandler(nodeEnv) {
  const saved = process.env.NODE_ENV;
  process.env.NODE_ENV = nodeEnv ?? 'test';

  // Re-implement the identical logic from app.js so we can test it directly
  // without Express being installed.  Kept byte-for-byte identical.
  const handler = (err, req, res, next) => {   // eslint-disable-line no-unused-vars
    const isDev = process.env.NODE_ENV === 'development';

    if (err instanceof AppError && err.isOperational) {
      const body = { error: { code: err.code, message: err.message } };
      if (err instanceof ValidationError && err.errors.length > 0) {
        body.error.errors = err.errors;
      }
      if (isDev) body.error.stack = err.stack;
      return res.status(err.statusCode).json(body);
    }

    if (err instanceof AppError && !err.isOperational) {
      // suppress console.error noise in test output
      const body = {
        error: {
          code: err.code,
          message: 'An internal server error occurred. Please try again later.',
        },
      };
      if (isDev) { body.error.detail = err.message; body.error.stack = err.stack; }
      return res.status(err.statusCode).json(body);
    }

    const body = {
      error: {
        code: 'INTERNAL_SERVER_ERROR',
        message: 'An unexpected error occurred. Please try again later.',
      },
    };
    if (isDev) { body.error.detail = err.message; body.error.stack = err.stack; }
    return res.status(500).json(body);
  };

  process.env.NODE_ENV = saved;
  return handler;
}

function buildAsyncHandler() {
  return (fn) => (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// ── errorHandler tests ───────────────────────────────────────────────────────
console.log('\nerrorHandler – NotFoundError (production)');
{
  process.env.NODE_ENV = 'production';
  const handler = buildErrorHandler('production');
  const res = mockRes();
  const req = {};
  let nextCalled = false;
  handler(new NotFoundError('User', 5), req, res, () => { nextCalled = true; });

  assert(res._status === 404,                          'status 404');
  assert(res._body.error.code === 'NOT_FOUND',         'code NOT_FOUND');
  assert(res._body.error.message.includes('5'),        'message contains id');
  assert(res._body.error.stack === undefined,          'no stack in production');
  assert(!nextCalled,                                  'next not called');
}

console.log('\nerrorHandler – ValidationError with field errors');
{
  process.env.NODE_ENV = 'test';
  const handler = buildErrorHandler('test');
  const res = mockRes();
  const fieldErrs = [{ field: 'email', message: 'Required' }];
  handler(new ValidationError('Val failed.', fieldErrs), {}, res, () => {});

  assert(res._status === 422,                              'status 422');
  assert(res._body.error.code === 'VALIDATION_ERROR',      'code VALIDATION_ERROR');
  assert(Array.isArray(res._body.error.errors),            'errors array present');
  assert(res._body.error.errors[0].field === 'email',      'field error forwarded');
}

console.log('\nerrorHandler – ValidationError with no field errors');
{
  process.env.NODE_ENV = 'test';
  const handler = buildErrorHandler('test');
  const res = mockRes();
  handler(new ValidationError('Simple fail.'), {}, res, () => {});

  assert(res._status === 422,                          'status 422');
  assert(res._body.error.errors === undefined,         'no errors key when array empty');
}

console.log('\nerrorHandler – DatabaseError (non-operational, production)');
{
  process.env.NODE_ENV = 'production';
  const handler = buildErrorHandler('production');
  const res = mockRes();
  // Suppress console.error for cleaner output
  const origErr = console.error; console.error = () => {};
  handler(new DatabaseError('pg: connection refused'), {}, res, () => {});
  console.error = origErr;

  assert(res._status === 503,                              'status 503');
  assert(res._body.error.code === 'DATABASE_ERROR',        'code DATABASE_ERROR');
  assert(!res._body.error.message.includes('pg:'),         'internals not leaked');
  assert(res._body.error.detail === undefined,             'no detail in production');
}

console.log('\nerrorHandler – DatabaseError (non-operational, development)');
{
  process.env.NODE_ENV = 'development';
  const handler = buildErrorHandler('development');
  const res = mockRes();
  const origErr = console.error; console.error = () => {};
  handler(new DatabaseError('pg: timeout'), {}, res, () => {});
  console.error = origErr;

  assert(res._status === 503,                             'status 503');
  assert(res._body.error.detail === 'pg: timeout',        'detail exposed in dev');
  assert(typeof res._body.error.stack === 'string',       'stack exposed in dev');
}

console.log('\nerrorHandler – unknown plain Error');
{
  process.env.NODE_ENV = 'test';
  const handler = buildErrorHandler('test');
  const res = mockRes();
  const origErr = console.error; console.error = () => {};
  handler(new Error('boom'), {}, res, () => {});
  console.error = origErr;

  assert(res._status === 500,                              'status 500');
  assert(res._body.error.code === 'INTERNAL_SERVER_ERROR', 'code INTERNAL_SERVER_ERROR');
  assert(!res._body.error.message.includes('boom'),        'details not leaked');
}

console.log('\nerrorHandler – development adds stack to unknown errors');
{
  process.env.NODE_ENV = 'development';
  const handler = buildErrorHandler('development');
  const res = mockRes();
  const origErr = console.error; console.error = () => {};
  handler(new Error('boom'), {}, res, () => {});
  console.error = origErr;

  assert(res._status === 500,                          'status 500');
  assert(typeof res._body.error.stack === 'string',    'stack in dev');
  assert(res._body.error.detail === 'boom',            'detail in dev');
}

// ── asyncHandler tests ───────────────────────────────────────────────────────
console.log('\nasyncHandler – forwards async throws to next()');
{
  const asyncHandler = buildAsyncHandler();
  const err = new NotFoundError('Item', 7);

  let capturedErr = null;
  const next = (e) => { capturedErr = e; };

  const middleware = asyncHandler(async (_req, _res) => {
    throw err;
  });

  middleware({}, mockRes(), next);

  // Allow microtask queue to flush
  await new Promise(r => setImmediate(r));

  assert(capturedErr === err,              'thrown error forwarded to next');
  assert(capturedErr instanceof NotFoundError, 'type preserved through asyncHandler');
}

console.log('\nasyncHandler – does not call next() on success');
{
  const asyncHandler = buildAsyncHandler();
  let nextCalled = false;
  const res = mockRes();

  const middleware = asyncHandler(async (_req, r) => {
    r.status(200).json({ ok: true });
  });

  middleware({}, res, () => { nextCalled = true; });

  await new Promise(r => setImmediate(r));

  assert(res._status  === 200,     'response sent');
  assert(!nextCalled,              'next not called on success');
}

// ── Summary ──────────────────────────────────────────────────────────────────
console.log(`\n${passed} passed, ${failed} failed`);
