 * ---------
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error so that:
 *   - instanceof checks work correctly throughout the codebase
 *   - stack traces are captured automatically
 *   - Express's error-handling middleware can branch on the type
 *
 * Usage (in a route handler):
 *   const { NotFoundError, ValidationError, DatabaseError } = require('./errors');
 *
 *   throw new NotFoundError('User not found');
 *   throw new ValidationError('Email is required');
 *   throw new DatabaseError('Query timed out');
 */

'use strict';

// ---------------------------------------------------------------------------
// Base application error
// ---------------------------------------------------------------------------

/**
 * AppError
 *
 * All custom errors inherit from this class.
 *
 * @property {number}  statusCode  - HTTP status code sent to the client
 * @property {string}  code        - Machine-readable error identifier
 * @property {boolean} isOperational
 *   true  → anticipated, safe-to-expose error (validation failure, not found …)
 *   false → unexpected programmer/infrastructure error; do NOT expose details
 */
class AppError extends Error {
  /**
   * @param {string} message      - Human-readable description (exposed to clients
   *                                only when isOperational === true)
   * @param {number} statusCode   - HTTP status code (default 500)
   * @param {string} code         - Machine-readable code  (default 'INTERNAL_ERROR')
   * @param {boolean} isOperational
   */
  constructor(
    message,
    statusCode = 500,
    code = 'INTERNAL_ERROR',
    isOperational = true
  ) {
    super(message);

    // Restore the correct prototype chain so instanceof works after transpilation
    Object.setPrototypeOf(this, new.target.prototype);

    this.name = new.target.name; // e.g. "NotFoundError"
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean V8 stack trace that starts at the call-site, not here
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, new.target);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * NotFoundError  (HTTP 404)
 *
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found');
 *   throw new NotFoundError(`Order ${id} not found`);
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message]   - Defaults to 'Resource not found'
   * @param {string} [resource]  - Optional resource name for richer context
   *                               e.g. 'User', 'Product'
   */
  constructor(message = 'Resource not found', resource = null) {
    super(message, 404, 'NOT_FOUND', true);
    if (resource) {
      this.resource = resource;
    }
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * ValidationError  (HTTP 422 Unprocessable Entity)
 *
 * Thrown when user-supplied input fails business-rule or schema validation.
 * Optionally carries a structured `fields` map so clients know exactly which
 * fields are invalid.
 *
