  /**
   * @param {string} [message]              - Defaults to 'Validation failed'
   * @param {Object.<string,string>} [fields]
   *   Optional map of  { fieldName: errorMessage }
   */
  constructor(message = 'Validation failed', fields = null) {
    super(message, 422, 'VALIDATION_ERROR', true);
