  //       Use a structured logger (e.g. pino, winston) in production.
  console.error({
    timestamp: new Date().toISOString(),
    method:    req.method,
    path:      req.path,
    statusCode,
    error: {
      name:    err.name  ?? 'Error',
      message: err.message,
      code:    isAppError ? err.code : 'INTERNAL_ERROR',
      stack:   err.stack,
    },
  });

  // ── 3. Build the client-facing payload ─────────────────────────────────
  const clientError = {
    code: isAppError ? err.code : 'INTERNAL_ERROR',
    // Only expose the real message for operational (anticipated) errors.
    // For unexpected errors send a safe, generic string.
    message: isOperational
      ? err.message
      : 'An unexpected error occurred. Please try again later.',
  };

  // Attach structured field errors for ValidationError
  if (isAppError && err instanceof ValidationError && err.fields) {
    clientError.fields = err.fields;
  }

  // Attach resource name for NotFoundError
  if (isAppError && err instanceof NotFoundError && err.resource) {
    clientError.resource = err.resource;
  }

  // ── 4. Send the response ────────────────────────────────────────────────
  res.status(statusCode).json({ error: clientError });
});

// ---------------------------------------------------------------------------
// Server bootstrap  (skipped when the module is required in tests)
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

