/**
 * smoke_test.js
 * Pure-Node validation of errors.js – no Express dependency needed.
 * Tests every class, property, instanceof chain and default value.
 */
'use strict';

const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let passed = 0;
let failed = 0;

function assert(label, condition) {
  if (condition) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}`);
    failed++;
  }
}

// ── AppError ────────────────────────────────────────────────────────────────
console.log('\nAppError');
const base = new AppError('base message', 400, 'BASE_CODE', true);
assert('instanceof Error',    base instanceof Error);
assert('instanceof AppError', base instanceof AppError);
assert('message',             base.message    === 'base message');
assert('statusCode',          base.statusCode === 400);
assert('code',                base.code       === 'BASE_CODE');
assert('isOperational',       base.isOperational === true);
assert('name',                base.name       === 'AppError');
assert('has stack',           typeof base.stack === 'string');

const baseDefaults = new AppError('msg');
assert('default statusCode',  baseDefaults.statusCode  === 500);
assert('default code',        baseDefaults.code        === 'INTERNAL_ERROR');
assert('default operational', baseDefaults.isOperational === true);

// ── NotFoundError ────────────────────────────────────────────────────────────
console.log('\nNotFoundError');
const nf = new NotFoundError('User 99 not found', 'User');
assert('instanceof Error',         nf instanceof Error);
assert('instanceof AppError',      nf instanceof AppError);
assert('instanceof NotFoundError', nf instanceof NotFoundError);
assert('message',                  nf.message    === 'User 99 not found');
assert('statusCode 404',           nf.statusCode === 404);
assert('code NOT_FOUND',           nf.code       === 'NOT_FOUND');
assert('isOperational true',       nf.isOperational === true);
assert('resource property',        nf.resource   === 'User');
assert('name',                     nf.name       === 'NotFoundError');

const nfDefaults = new NotFoundError();
assert('default message',   nfDefaults.message    === 'Resource not found');
assert('no resource prop',  nfDefaults.resource   === undefined);

// ── ValidationError ──────────────────────────────────────────────────────────
console.log('\nValidationError');
const ve = new ValidationError('Invalid body', { email: 'required', name: 'too short' });
assert('instanceof Error',           ve instanceof Error);
assert('instanceof AppError',        ve instanceof AppError);
assert('instanceof ValidationError', ve instanceof ValidationError);
assert('message',                    ve.message    === 'Invalid body');
assert('statusCode 422',             ve.statusCode === 422);
assert('code VALIDATION_ERROR',      ve.code       === 'VALIDATION_ERROR');
assert('isOperational true',         ve.isOperational === true);
assert('fields.email',               ve.fields.email === 'required');
assert('fields.name',                ve.fields.name  === 'too short');
assert('name',                       ve.name         === 'ValidationError');

const veDefaults = new ValidationError();
assert('default message', veDefaults.message === 'Validation failed');
assert('no fields prop',  veDefaults.fields   === undefined);

const veSingleMsg = new ValidationError('Email is required');
assert('message without fields', veSingleMsg.message === 'Email is required');
assert('no fields prop (null)',   veSingleMsg.fields   === undefined);

// ── DatabaseError ────────────────────────────────────────────────────────────
console.log('\nDatabaseError');
const de = new DatabaseError('Connection refused');
assert('instanceof Error',        de instanceof Error);
assert('instanceof AppError',     de instanceof AppError);
assert('instanceof DatabaseError',de instanceof DatabaseError);
assert('message',                 de.message    === 'Connection refused');
assert('statusCode 503',          de.statusCode === 503);
assert('code DATABASE_ERROR',     de.code       === 'DATABASE_ERROR');
assert('isOperational FALSE',     de.isOperational === false);  // default non-op
assert('name',                    de.name       === 'DatabaseError');

const deOperational = new DatabaseError('Unique constraint violated', true);
assert('isOperational TRUE when set', deOperational.isOperational === true);

const deDefaults = new DatabaseError();
assert('default message', deDefaults.message === 'A database error occurred');

// ── Cross-class instanceof isolation ─────────────────────────────────────────
console.log('\nCross-class isolation');
assert('NotFoundError   NOT instanceof ValidationError', !(nf instanceof ValidationError));
assert('NotFoundError   NOT instanceof DatabaseError',   !(nf instanceof DatabaseError));
assert('ValidationError NOT instanceof NotFoundError',   !(ve instanceof NotFoundError));
assert('ValidationError NOT instanceof DatabaseError',   !(ve instanceof DatabaseError));
assert('DatabaseError   NOT instanceof NotFoundError',   !(de instanceof NotFoundError));
assert('DatabaseError   NOT instanceof ValidationError', !(de instanceof ValidationError));

// ── Error handler branching simulation ───────────────────────────────────────
console.log('\nError-handler branching (simulated middleware)');

function simulateErrorHandler(err) {
  const isAppError   = err instanceof AppError;
  const statusCode   = isAppError ? err.statusCode : 500;
  const isOperational = isAppError ? err.isOperational : false;

  const clientError = {
    code: isAppError ? err.code : 'INTERNAL_ERROR',
    message: isOperational
      ? err.message
      : 'An unexpected error occurred. Please try again later.',
  };
  if (err instanceof ValidationError && err.fields) clientError.fields = err.fields;
  if (err instanceof NotFoundError   && err.resource) clientError.resource = err.resource;

  return { statusCode, body: { error: clientError } };
}

const r1 = simulateErrorHandler(new NotFoundError('User 5 not found', 'User'));
assert('NotFoundError → 404',            r1.statusCode === 404);
assert('NotFoundError → NOT_FOUND code', r1.body.error.code === 'NOT_FOUND');
assert('NotFoundError → message shown',  r1.body.error.message === 'User 5 not found');
assert('NotFoundError → resource shown', r1.body.error.resource === 'User');

const r2 = simulateErrorHandler(new ValidationError('Bad input', { x: 'required' }));
assert('ValidationError → 422',                r2.statusCode === 422);
assert('ValidationError → VALIDATION_ERROR',   r2.body.error.code === 'VALIDATION_ERROR');
assert('ValidationError → message shown',      r2.body.error.message === 'Bad input');
assert('ValidationError → fields attached',    r2.body.error.fields.x === 'required');

const r3 = simulateErrorHandler(new DatabaseError('pool exhausted'));
assert('DatabaseError → 503',                  r3.statusCode === 503);
assert('DatabaseError → DATABASE_ERROR code',  r3.body.error.code === 'DATABASE_ERROR');
assert('DatabaseError → message hidden',       r3.body.error.message !== 'pool exhausted');
assert('DatabaseError → generic message',      r3.body.error.message.includes('unexpected'));

const r4 = simulateErrorHandler(new TypeError('oops'));
assert('Unknown Error → 500',               r4.statusCode === 500);
assert('Unknown Error → INTERNAL_ERROR',    r4.body.error.code === 'INTERNAL_ERROR');
assert('Unknown Error → message hidden',    r4.body.error.message.includes('unexpected'));

// ── Summary ──────────────────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(50)}`);
console.log(`Results: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);

