const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

// --- AppError base ---
const base = new AppError('base msg', 418, 'TEAPOT');
console.assert(base.message    === 'base msg',    'AppError: message');
console.assert(base.statusCode === 418,           'AppError: statusCode');
console.assert(base.code       === 'TEAPOT',      'AppError: code');
console.assert(base.isOperational === true,       'AppError: isOperational default');
console.assert(base.name       === 'AppError',    'AppError: name');
console.assert(base instanceof Error,             'AppError: instanceof Error');

// --- NotFoundError ---
const nfe = new NotFoundError('User not found', 'USER_NOT_FOUND');
console.assert(nfe.statusCode  === 404,              'NotFoundError: statusCode');
console.assert(nfe.code        === 'USER_NOT_FOUND', 'NotFoundError: code');
console.assert(nfe.isOperational === true,           'NotFoundError: isOperational');
console.assert(nfe instanceof AppError,              'NotFoundError: instanceof AppError');
console.assert(nfe instanceof Error,                 'NotFoundError: instanceof Error');

// NotFoundError defaults
const nfeDefault = new NotFoundError();
console.assert(nfeDefault.message    === 'Resource not found', 'NotFoundError: default message');
console.assert(nfeDefault.code       === 'NOT_FOUND',          'NotFoundError: default code');

// --- ValidationError ---
const ve = new ValidationError('Bad input', 'BAD_INPUT', { email: 'required' });
console.assert(ve.statusCode  === 422,           'ValidationError: statusCode');
console.assert(ve.code        === 'BAD_INPUT',   'ValidationError: code');
console.assert(ve.isOperational === true,        'ValidationError: isOperational');
console.assert(ve.fields.email === 'required',   'ValidationError: fields');
console.assert(ve instanceof AppError,           'ValidationError: instanceof AppError');

// ValidationError defaults
const veDefault = new ValidationError();
console.assert(veDefault.message === 'Validation failed',   'ValidationError: default message');
console.assert(veDefault.code    === 'VALIDATION_ERROR',    'ValidationError: default code');
console.assert(JSON.stringify(veDefault.fields) === '{}',   'ValidationError: default fields');

// --- DatabaseError ---
const cause = new Error('ECONNREFUSED');
const dbe = new DatabaseError('DB down', 'DB_DOWN', cause);
console.assert(dbe.statusCode    === 503,      'DatabaseError: statusCode');
console.assert(dbe.code          === 'DB_DOWN','DatabaseError: code');
console.assert(dbe.isOperational === false,    'DatabaseError: isOperational is false');
console.assert(dbe.cause         === cause,    'DatabaseError: cause preserved');
console.assert(dbe instanceof AppError,        'DatabaseError: instanceof AppError');

// DatabaseError defaults
const dbeDefault = new DatabaseError();
console.assert(dbeDefault.message === 'A database error occurred', 'DatabaseError: default message');
console.assert(dbeDefault.code    === 'DATABASE_ERROR',            'DatabaseError: default code');
console.assert(dbeDefault.cause   === null,                        'DatabaseError: default cause is null... wait');
// cause is null so the if(cause) branch is skipped; property should be absent
console.assert(!('cause' in dbeDefault),                           'DatabaseError: no cause property when null');

console.log('All errors.js assertions passed.');
"

