/**
 * errors.js
 *
 * Centralised custom error classes for the application.
 *
 * Every class extends the built-in Error and carries:
 *   - statusCode  – the HTTP status code sent to the client
 *   - code        – a stable machine-readable string (useful for client-side
 *                   branching and log searches)
 *   - isOperational – distinguishes expected, "safe" errors (operational) from
 *                     unexpected programming errors so the global handler can
 *                     decide whether to restart the process in production.
 */

'use strict';

// ---------------------------------------------------------------------------
// Base class
// ---------------------------------------------------------------------------

class AppError extends Error {
  /**
   * @param {string}  message         - Human-readable description of the error.
   * @param {number}  statusCode       - HTTP status code (e.g. 404, 422, 500).
   * @param {string}  code             - Machine-readable error identifier.
   * @param {boolean} [isOperational]  - Set to false only for unexpected bugs.
   */
  constructor(message, statusCode, code, isOperational = true) {
    super(message);

    // Maintain the correct class name in stack traces
    this.name = this.constructor.name;

    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = isOperational;

    // Capture a clean V8 stack trace that starts at the call site, not inside
    // this constructor.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// 404 – Not Found
// ---------------------------------------------------------------------------

/**
 * Thrown when a requested resource does not exist.
 *
 * @example
 *   throw new NotFoundError('User not found', 'USER_NOT_FOUND');
 *   throw new NotFoundError(`Product ${id} not found`);   // code defaults to 'NOT_FOUND'
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message] - Defaults to 'Resource not found'.
   * @param {string} [code]    - Defaults to 'NOT_FOUND'.
   */
  constructor(message = 'Resource not found', code = 'NOT_FOUND') {
    super(message, 404, code);
  }
}

// ---------------------------------------------------------------------------
// 422 – Validation Error
// ---------------------------------------------------------------------------

/**
 * Thrown when request input fails validation.
 * Optionally carries a `fields` map so the client knows exactly which
 * fields are invalid.
 *
 * @example
 *   throw new ValidationError('Invalid request body');
 *   throw new ValidationError('Validation failed', 'VALIDATION_ERROR', {
 *     email: 'Must be a valid email address',
 *     age:   'Must be a positive integer',
 *   });
 */
class ValidationError extends AppError {
  /**
   * @param {string} [message]         - Defaults to 'Validation failed'.
   * @param {string} [code]            - Defaults to 'VALIDATION_ERROR'.
   * @param {Object} [fields]          - Optional map of { fieldName: errorMessage }.
   */
  constructor(message = 'Validation failed', code = 'VALIDATION_ERROR', fields = {}) {
    super(message, 422, code);
    // Per-field detail so API consumers can show inline form errors
    this.fields = fields;
  }
}

// ---------------------------------------------------------------------------
// 503 – Database Error
// ---------------------------------------------------------------------------

/**
 * Thrown when a database operation fails (connection error, query timeout,
 * constraint violation that was not caught earlier, etc.).
 * Uses 503 Service Unavailable so clients know to retry; change to 500 if
 * you prefer to signal an unrecoverable internal fault instead.
 *
 * The original database error is stored under `this.cause` so it can be
 * inspected and logged server-side without leaking details to the client.
 *
 * @example
 *   throw new DatabaseError('Could not reach the database');
 *   throw new DatabaseError('Query timed out', 'DB_TIMEOUT', originalError);
 */
class DatabaseError extends AppError {
  /**
   * @param {string} [message]      - Defaults to 'A database error occurred'.
   * @param {string} [code]         - Defaults to 'DATABASE_ERROR'.
   * @param {Error}  [cause]        - The underlying error from the DB driver.
   */
  constructor(
    message = 'A database error occurred',
    code = 'DATABASE_ERROR',
    cause = null,
  ) {
    // DatabaseError is treated as operational (expected) by default because
    // transient DB failures are common in production; however the handler will
    // still return a 503 and should alert on-call if needed.
    super(message, 503, code);
    if (cause) {
      // `cause` is the standard Error property introduced in Node 16.9
      this.cause = cause;
    }
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { AppError, NotFoundError, ValidationError, DatabaseError };

'use strict';

// ---------------------------------------------------------------------------
// Dependencies
// ---------------------------------------------------------------------------

const express = require('express');
const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

const app = express();

// Parse JSON request bodies so routes can read req.body
app.use(express.json());

// ---------------------------------------------------------------------------
// In-memory "database" – replaced by real DB calls in production
// ---------------------------------------------------------------------------

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// Helper – simulate an async data-access layer
// ---------------------------------------------------------------------------

/**
 * Fetch all users.
 * Wraps any unexpected storage error in a DatabaseError so the route stays
 * free of low-level error handling.
 *
 * @returns {Promise<Array>}
 */
async function fetchAllUsers() {
  try {
    // Replace with real DB query, e.g. db.query('SELECT * FROM users')
    return USERS;
  } catch (err) {
    throw new DatabaseError('Failed to retrieve users', 'DB_FETCH_USERS', err);
  }
}

/**
 * Fetch a single user by numeric id.
 *
 * @param   {number} id
 * @returns {Promise<Object>}
 * @throws  {NotFoundError}  When no user matches the given id.
 * @throws  {DatabaseError}  When the underlying storage call fails.
 */
async function fetchUserById(id) {
  try {
    // Replace with real DB query, e.g. db.query('SELECT * FROM users WHERE id = $1', [id])
    const user = USERS.find((u) => u.id === id);
    if (!user) {
      throw new NotFoundError(`User with id ${id} not found`, 'USER_NOT_FOUND');
    }
    return user;
  } catch (err) {
    // Re-throw operational errors (NotFoundError, etc.) without wrapping them
    if (err instanceof AppError) throw err;
    throw new DatabaseError('Failed to retrieve user', 'DB_FETCH_USER', err);
  }
}

/**
 * Validate the fields required to create a new user.
 *
 * @param   {Object} body - The parsed request body.
 * @throws  {ValidationError} When one or more fields are missing or invalid.
 */
function validateCreateUser(body) {
  const fieldErrors = {};

  if (!body.name || typeof body.name !== 'string' || body.name.trim() === '') {
    fieldErrors.name = 'name is required and must be a non-empty string';
  }

  if (!body.email || typeof body.email !== 'string') {
    fieldErrors.email = 'email is required and must be a string';
  } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email)) {
    fieldErrors.email = 'email must be a valid email address';
  }

  if (Object.keys(fieldErrors).length > 0) {
    throw new ValidationError('Request body validation failed', 'VALIDATION_ERROR', fieldErrors);
  }
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe – always returns 200 while the process is running.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 */
app.get('/users', async (req, res, next) => {
  try {
    const users = await fetchAllUsers();
    res.json(users);
  } catch (err) {
    // Hand off to the centralised error handler
    next(err);
  }
});

/**
 * GET /users/:id
 * Returns a single user by id.
 *
 * Throws NotFoundError  – if the user does not exist.
 * Throws ValidationError – if :id is not a valid integer.
 */
app.get('/users/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        'Route parameter :id must be a positive integer',
        'INVALID_PARAM_ID',
        { id: 'Must be a positive integer' },
      );
    }

    const user = await fetchUserById(id);
    res.json(user);
  } catch (err) {
    next(err);
  }
});

/**
 * POST /users
 * Creates a new user.
 *
 * Throws ValidationError – if name or email are missing/malformed.
 */
app.post('/users', async (req, res, next) => {
  try {
    validateCreateUser(req.body);

    // Replace with real INSERT in production
    const newUser = {
      id:    USERS.length + 1,
      name:  req.body.name.trim(),
      email: req.body.email.trim(),
    };
    USERS.push(newUser);

    res.status(201).json(newUser);
  } catch (err) {
    next(err);
  }
});

/**
 * DELETE /users/:id
 * Removes a user by id.
 *
 * Throws ValidationError – if :id is not a valid integer.
 * Throws NotFoundError   – if the user does not exist.
 */
app.delete('/users/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      throw new ValidationError(
        'Route parameter :id must be a positive integer',
        'INVALID_PARAM_ID',
        { id: 'Must be a positive integer' },
      );
    }

    // Reuse the same lookup helper – it throws NotFoundError if missing
    await fetchUserById(id);

    const index = USERS.findIndex((u) => u.id === id);
    USERS.splice(index, 1);

    // 204 No Content – successful deletion with no response body
    res.status(204).send();
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all – must come AFTER all defined routes
// ---------------------------------------------------------------------------

/**
 * Any request that didn't match a route above falls through to here.
 * We throw (via next) so the error handler below formats it consistently.
 */
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`, 'ROUTE_NOT_FOUND'));
});

// ---------------------------------------------------------------------------
// Centralised error-handling middleware
// ---------------------------------------------------------------------------

/**
 * Express identifies error-handling middleware by its four-argument signature
 * (err, req, res, next).  It MUST be registered last, after all routes and
 * other middleware.
 *
 * Behaviour:
 *  - Operational AppError subclasses  → use their own statusCode + code.
 *  - Unknown / programming errors     → 500 Internal Server Error.
 *  - Stack traces are only included   → when NODE_ENV !== 'production', so
 *                                       they never leak to real users.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // ------------------------------------------------------------------
  // 1. Determine whether this is a known, operational error
  // ------------------------------------------------------------------
  const isOperational = err instanceof AppError && err.isOperational;

  const statusCode = isOperational ? err.statusCode : 500;
  const code       = isOperational ? err.code       : 'INTERNAL_SERVER_ERROR';
  const message    = isOperational ? err.message    : 'An unexpected error occurred';

  // ------------------------------------------------------------------
  // 2. Log the full error server-side (replace with your logger)
  // ------------------------------------------------------------------
  if (statusCode >= 500) {
    // Unexpected errors → log the full stack for debugging
    console.error('[ERROR]', {
      code,
      statusCode,
      message:    err.message,
      stack:      err.stack,
      // Avoid logging req.body in production – may contain PII
      path:       req.path,
      method:     req.method,
    });
  } else {
    // Operational 4xx errors → info-level, no stack needed
    console.info('[WARN]', { code, statusCode, message: err.message, path: req.path });
  }

  // ------------------------------------------------------------------
  // 3. Build the client-facing response
  // ------------------------------------------------------------------
  const body = {
    error: {
      code,
      message,
      // Per-field detail is safe to expose to the client
      ...(isOperational && err.fields && Object.keys(err.fields).length > 0
        ? { fields: err.fields }
        : {}),
      // Stack traces only in non-production environments
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    },
  };

  res.status(statusCode).json(body);
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

