'use strict';
// ─────────────────────────────────────────────────────────────────────────────
// Standalone smoke-test: loads errors.js and tests every error class + the
// centralised handler logic extracted from app.js — no Express needed.
// ─────────────────────────────────────────────────────────────────────────────

const { AppError, NotFoundError, ValidationError, DatabaseError } = require('./errors');

let passed = 0;
let failed = 0;

function assert(label, condition) {
  if (condition) {
    console.log(`  ✓  ${label}`);
    passed++;
  } else {
    console.error(`  ✗  ${label}`);
    failed++;
  }
}

// ── AppError (base) ──────────────────────────────────────────────────────────
console.log('\n[AppError]');
const base = new AppError('Something went wrong', 500, 'GENERIC', false);
assert('instanceof Error',    base instanceof Error);
assert('instanceof AppError', base instanceof AppError);
assert('name = AppError',     base.name        === 'AppError');
assert('statusCode = 500',    base.statusCode  === 500);
assert('code = GENERIC',      base.code        === 'GENERIC');
assert('isOperational false', base.isOperational === false);
assert('message preserved',   base.message     === 'Something went wrong');
assert('stack is a string',   typeof base.stack === 'string');

// ── NotFoundError ────────────────────────────────────────────────────────────
console.log('\n[NotFoundError]');
const nfe = new NotFoundError('User with id 99 not found', 'USER_NOT_FOUND');
assert('instanceof AppError',    nfe instanceof AppError);
assert('instanceof NotFoundError', nfe instanceof NotFoundError);
assert('statusCode = 404',       nfe.statusCode  === 404);
assert('code = USER_NOT_FOUND',  nfe.code        === 'USER_NOT_FOUND');
assert('isOperational = true',   nfe.isOperational === true);
assert('name = NotFoundError',   nfe.name        === 'NotFoundError');

const nfeDefault = new NotFoundError();
assert('default message',  nfeDefault.message === 'Resource not found');
assert('default code',     nfeDefault.code    === 'NOT_FOUND');

// ── ValidationError ──────────────────────────────────────────────────────────
console.log('\n[ValidationError]');
const fields = { email: 'Invalid format', age: 'Must be positive' };
const ve = new ValidationError('Validation failed', 'VALIDATION_ERROR', fields);
